const Q=[];
const q=(m,t,s,o,a,w,src)=>Q.push({id:'q'+(Q.length+1),m,t,s,o,a,w,src});

/* ===== LUẬT GIÁ 2023 ===== */
q(1,'luatgia','Luật Giá 2023 bắt đầu có hiệu lực từ ngày nào?',['01/01/2024','01/07/2024','01/01/2025','01/07/2023'],1,'Luật Giá 2023 có hiệu lực từ 01/07/2024. Nghị định 85/2024/NĐ-CP (hướng dẫn Luật) và 78/2024/NĐ-CP (hướng dẫn về thẩm định giá) ra đời để thi hành.','CĐ1A Pháp luật về TĐG; Luật Giá Đ.74');
q(1,'luatgia','Theo Luật Giá 2023, bản chất của hoạt động thẩm định giá là gì?',['Hoạt động quản lý nhà nước quyết định giá tài sản','Hoạt động tư vấn xác định giá trị tài sản tại một địa điểm, thời điểm, cho một mục đích nhất định','Hoạt động xác lập giá bán cuối cùng cho giao dịch','Hoạt động kiểm tra yếu tố hình thành giá'],1,'Điều 4 khoản 16: thẩm định giá là hoạt động TƯ VẤN xác định giá trị tài sản, do doanh nghiệp thẩm định giá hoặc hội đồng thẩm định giá thực hiện theo Chuẩn mực. Quyết định giá cuối cùng vẫn thuộc chủ sở hữu hoặc người có thẩm quyền, nên thẩm định giá không phải là "định giá".','Luật Giá Đ.4 k16; CĐ2 mục 2.2.1.1');
q(1,'luatgia','Nguyên tắc hoạt động thẩm định giá tại Điều 41 Luật Giá gồm những nội dung nào?',['Tuân thủ pháp luật và Chuẩn mực; độc lập, khách quan, trung thực; chịu trách nhiệm về hoạt động thẩm định giá','Bảo đảm lợi nhuận cho khách hàng; trung thực; bảo mật','Tuân thủ chỉ đạo của cơ quan nhà nước; độc lập; công khai giá','Theo yêu cầu của khách hàng; khách quan; bồi thường thiệt hại'],0,'Điều 41 có đúng ba nguyên tắc: (1) tuân thủ pháp luật, Chuẩn mực thẩm định giá VN; (2) độc lập, khách quan, trung thực; (3) chịu trách nhiệm theo quy định của pháp luật. Các phương án khác pha thêm nội dung không có trong điều luật.','Luật Giá Đ.41');
q(1,'luatgia','Ai ban hành Chuẩn mực thẩm định giá Việt Nam?',['Quốc hội','Chính phủ','Bộ trưởng Bộ Tài chính','Hội Thẩm định giá Việt Nam'],2,'Điều 42 Luật Giá: Bộ trưởng Bộ Tài chính ban hành, theo dõi việc thực hiện, rà soát và kiến nghị sửa các quy định mâu thuẫn, chồng chéo. Hội nghề nghiệp không có thẩm quyền ban hành chuẩn mực.','Luật Giá Đ.42');
q(1,'luatgia','Hoạt động thẩm định giá theo Luật Giá gồm hai loại nào?',['Thẩm định giá tài sản và thẩm định giá doanh nghiệp','Cung cấp dịch vụ thẩm định giá (do doanh nghiệp thẩm định giá, qua hợp đồng dân sự) và thẩm định giá của Nhà nước (do hội đồng thẩm định giá)','Thẩm định giá bắt buộc và thẩm định giá tự nguyện','Thẩm định giá trong nước và thẩm định giá nước ngoài'],1,'Điều 40: dịch vụ thẩm định giá do doanh nghiệp thực hiện, giao kết bằng hợp đồng dân sự; thẩm định giá của Nhà nước do hội đồng thẩm định giá thực hiện theo quyết định của người có thẩm quyền (Điều 59). Phương án A là cách phân loại theo lĩnh vực của thẻ thẩm định viên, không phải theo hoạt động.','Luật Giá Đ.40');
q(1,'luatgia','Hoạt động nào sau đây KHÔNG nằm trong các hoạt động điều tiết giá?',['Bình ổn giá','Hiệp thương giá','Kê khai giá, niêm yết giá','Thẩm định giá của doanh nghiệp thẩm định giá'],3,'Các hoạt động điều tiết giá: bình ổn giá, định giá, hiệp thương giá, kê khai giá, niêm yết giá, giá tham chiếu, kiểm tra yếu tố hình thành giá. Thẩm định giá là hoạt động tư vấn xác định giá trị, không phải biện pháp điều tiết của Nhà nước.','CĐ1A; Luật Giá Đ.4 k8');
q(1,'luatgia','"Định giá" khác "thẩm định giá" ở điểm cốt lõi nào?',['Định giá là việc cơ quan nhà nước có thẩm quyền hoặc tổ chức, cá nhân kinh doanh xác định giá của hàng hóa, dịch vụ; thẩm định giá là tư vấn xác định giá trị tài sản','Hai khái niệm hoàn toàn đồng nghĩa','Định giá chỉ áp dụng cho bất động sản','Thẩm định giá có tính bắt buộc, định giá thì không'],0,'Điều 4 khoản 11: định giá là quá trình cơ quan nhà nước hoặc tổ chức, cá nhân kinh doanh xác định GIÁ của hàng hóa, dịch vụ (chủ thể có quyền quyết định). Thẩm định giá chỉ là tư vấn nên không ràng buộc người quyết định.','Luật Giá Đ.4 k11');
q(1,'luatgia','Giá dịch vụ thẩm định giá do ai và theo nguyên tắc nào xác định?',['Bộ Tài chính quy định khung giá','Do doanh nghiệp thẩm định giá và khách hàng thỏa thuận trong hợp đồng, bảo đảm bù đắp chi phí thực tế hợp lý','Do hội nghề nghiệp công bố','Tính theo phần trăm giá trị tài sản bắt buộc'],1,'Điều 57: giá dịch vụ ghi trong hợp đồng, theo giao dịch dân sự giữa doanh nghiệp và khách hàng, phải bảo đảm nguyên tắc bù đắp chi phí thực tế hợp lý để thực hiện đầy đủ phạm vi công việc theo Chuẩn mực.','Luật Giá Đ.57');
q(1,'luatgia','Phương thức giải quyết tranh chấp về hợp đồng thẩm định giá theo Luật Giá là gì?',['Chỉ được khởi kiện ra Tòa án','Thương lượng, hòa giải; trọng tài thương mại; khởi kiện tại Tòa án','Chỉ qua Bộ Tài chính phân xử','Chỉ qua Hội Thẩm định giá'],1,'Điều 58 liệt kê ba phương thức: thương lượng/hòa giải theo cam kết trong hợp đồng; trọng tài thương mại; khởi kiện tại Tòa án theo tố tụng dân sự.','Luật Giá Đ.58');
q(1,'luatgia','Cơ quan nào chịu trách nhiệm trước Chính phủ thực hiện chức năng quản lý nhà nước về giá?',['Bộ Kế hoạch và Đầu tư','Bộ Tài chính','Ngân hàng Nhà nước','Bộ Công Thương'],1,'Chính phủ thống nhất quản lý nhà nước về giá; Bộ Tài chính chịu trách nhiệm trước Chính phủ; các bộ quản lý trong lĩnh vực mình phụ trách; UBND cấp tỉnh quản lý tại địa phương.','Luật Giá Đ.12–16');
q(1,'luatgia','Hành vi nào sau đây là hành vi bị cấm đối với tổ chức, cá nhân theo Điều 7 Luật Giá?',['Niêm yết giá đúng quy định','Cản trở hoạt động quản lý, điều tiết giá, thẩm định giá của cơ quan nhà nước có thẩm quyền','Kê khai giá đúng hạn','Tham gia hội nghề nghiệp về thẩm định giá'],1,'Điều 7 khoản 2 cấm loan tin sai sự thật gây nhiễu loạn thị trường, gian lận về giá, lợi dụng thiên tai dịch bệnh để tăng giá trục lợi, cản trở hoạt động quản lý, điều tiết giá và thẩm định giá. Các phương án còn lại là hành vi hợp pháp.','Luật Giá Đ.7 k2');
q(1,'luatgia','Mặt hàng nào sau đây thuộc danh mục hàng hóa, dịch vụ thực hiện bình ổn giá (Phụ lục 1 Luật Giá)?',['Sữa dành cho trẻ em dưới 06 tuổi','Thịt lợn','Điện thoại di động','Dịch vụ du lịch'],0,'Danh mục bình ổn giá gồm: xăng dầu thành phẩm; LPG; sữa dành cho trẻ em dưới 06 tuổi; thóc tẻ, gạo tẻ; phân đạm, DAP, NPK; thức ăn chăn nuôi, thủy sản; vắc-xin phòng bệnh cho gia súc, gia cầm; thuốc bảo vệ thực vật; thuốc thiết yếu tại cơ sở khám chữa bệnh.','Luật Giá Phụ lục 1; CĐ1A');

/* ===== THẺ & THẨM ĐỊNH VIÊN ===== */
q(1,'tdv','Điều kiện để được dự thi cấp thẻ thẩm định viên về giá (Điều 44) gồm:',['Năng lực hành vi dân sự đầy đủ; bằng đại học trở lên; chứng chỉ đào tạo nghiệp vụ thẩm định giá phù hợp lĩnh vực (trừ người có bằng cao đẳng trở lên chuyên ngành giá hoặc thẩm định giá)','Có bằng cao đẳng trở lên và 36 tháng kinh nghiệm','Có hợp đồng lao động với doanh nghiệp thẩm định giá','Là cán bộ, công chức ngành tài chính'],0,'Điều 44 khoản 2: ba điều kiện (a) năng lực hành vi, (b) bằng đại học trở lên, (c) chứng chỉ đào tạo nghiệp vụ TĐG, trừ trường hợp có bằng CĐ trở lên chuyên ngành giá/thẩm định giá. 36 tháng và hợp đồng lao động là điều kiện ĐĂNG KÝ HÀNH NGHỀ (Điều 45), không phải điều kiện dự thi.','Luật Giá Đ.44');
q(1,'tdv','Thẩm định viên về giá là ai theo Điều 46 Luật Giá?',['Người có thẻ thẩm định viên về giá','Người có thẻ, đã đăng ký hành nghề thẩm định giá và được Bộ Tài chính thông báo là thẩm định viên về giá','Người có chứng chỉ đào tạo nghiệp vụ thẩm định giá','Người làm việc tại doanh nghiệp thẩm định giá'],1,'Có thẻ mới chỉ là điều kiện cần. Phải đăng ký hành nghề qua doanh nghiệp thẩm định giá và được Bộ Tài chính thông báo thì mới là "thẩm định viên về giá" và được ký chứng thư, báo cáo.','Luật Giá Đ.46');
q(1,'tdv','Tổng thời gian thực tế làm việc tối thiểu (trình độ đại học trở lên) để đăng ký hành nghề thẩm định giá là bao nhiêu?',['12 tháng','24 tháng, mọi trường hợp','36 tháng; được rút xuống 24 tháng nếu làm việc theo chương trình định hướng ứng dụng đại học trở lên về chuyên ngành giá hoặc thẩm định giá','60 tháng'],2,'Điều 45 khoản 1 điểm c: đủ 36 tháng làm việc tại doanh nghiệp thẩm định giá, cơ quan quản lý nhà nước về giá và thẩm định giá; 24 tháng với trường hợp đại học trở lên chuyên ngành giá/TĐG theo chương trình định hướng ứng dụng.','Luật Giá Đ.45 k1c');
q(1,'tdv','Đối tượng nào KHÔNG được hành nghề thẩm định giá?',['Người có thẻ và có hợp đồng lao động với doanh nghiệp thẩm định giá','Cán bộ, công chức; sĩ quan, quân nhân chuyên nghiệp, công nhân quốc phòng; sĩ quan, hạ sĩ quan, công nhân công an','Người đã qua 36 tháng làm việc','Người đã cập nhật kiến thức'],1,'Điều 45 khoản 2: gồm cán bộ, công chức; lực lượng quân đội, công an theo danh sách luật; người đang bị cấm hành nghề, bị khởi tố/truy tố/xét xử, đã bị kết án một số tội kinh tế, chức vụ chưa xóa án tích; người đang bị tước thẻ.','Luật Giá Đ.45 k2');
q(1,'tdv','Một người có thẻ thẩm định viên về giá có được đăng ký hành nghề đồng thời tại hai doanh nghiệp thẩm định giá không?',['Có, nếu có hợp đồng lao động với cả hai','Có, nếu được Bộ Tài chính đồng ý','Không được đăng ký hành nghề đồng thời tại hai doanh nghiệp thẩm định giá trở lên','Chỉ được nếu là thành viên góp vốn'],2,'Điều 45 khoản 3 cấm đăng ký đồng thời tại 2 doanh nghiệp trở lên, nhằm gắn trách nhiệm nghề nghiệp vào một doanh nghiệp duy nhất.','Luật Giá Đ.45 k3');
q(1,'tdv','Người có thẻ thẩm định viên lĩnh vực THẨM ĐỊNH GIÁ TÀI SẢN có được thực hiện thẩm định giá doanh nghiệp không?',['Có, vì doanh nghiệp là một loại tài sản','Không; chỉ người có thẻ lĩnh vực thẩm định giá doanh nghiệp mới được thẩm định giá doanh nghiệp','Có, nếu có thêm chứng chỉ ngoại ngữ','Có, nếu doanh nghiệp thẩm định giá cho phép'],1,'Thẻ chia hai lĩnh vực: tài sản và doanh nghiệp. Người có thẻ lĩnh vực doanh nghiệp được đăng ký hành nghề cả hai lĩnh vực; chiều ngược lại thì không. Ký chứng thư không đúng lĩnh vực chuyên môn là hành vi bị cấm.','Luật Giá Đ.44, 45 k3, 7 k4');
q(1,'tdv','Điều kiện "đã cập nhật kiến thức về thẩm định giá" khi đăng ký hành nghề được miễn trong trường hợp nào?',['Thẻ được cấp dưới 01 năm tính đến thời điểm đăng ký hành nghề','Có bằng thạc sĩ','Đã làm việc trên 5 năm','Không có trường hợp miễn'],0,'Điều 45 khoản 1 điểm d miễn cập nhật kiến thức đối với thẻ được cấp dưới 01 năm tính đến thời điểm đăng ký.','Luật Giá Đ.45 k1d');
q(1,'tdv','Hành vi nào sau đây thẩm định viên về giá bị nghiêm cấm?',['Đưa ra quan điểm độc lập về chuyên môn','Lập chứng thư thẩm định giá, báo cáo thẩm định giá với tư cách cá nhân','Từ chối thẩm định giá khi hồ sơ không đủ tin cậy','Tham gia tổ chức nghề nghiệp'],1,'Điều 7 khoản 4 cấm: thông tin sai về trình độ; giả mạo, cho thuê, cho mượn thẻ; lập chứng thư/báo cáo với tư cách cá nhân; ký sai lĩnh vực hoặc khi không đủ điều kiện; thẩm định giá cho người có liên quan; lập khống; mua chuộc, thông đồng. Các phương án còn lại là QUYỀN của thẩm định viên.','Luật Giá Đ.7 k4, Đ.47');
q(1,'tdv','Thẩm định viên có quyền từ chối thực hiện thẩm định giá trong trường hợp nào?',['Khi khách hàng yêu cầu giá thấp hơn mong muốn','Không đúng lĩnh vực chuyên môn được phép hành nghề, hoặc hồ sơ, tài liệu không đủ hoặc không bảo đảm tin cậy','Khi tài sản ở xa trụ sở','Khi khách hàng chưa trả phí'],1,'Điều 47: thẩm định viên được từ chối khi không đúng lĩnh vực hoặc hồ sơ, tài liệu thiếu hay không đáng tin cậy. Phí và khoảng cách không phải căn cứ luật định.','Luật Giá Đ.47');

/* ===== DOANH NGHIỆP THẨM ĐỊNH GIÁ ===== */
q(1,'dntdg','Điều kiện chung để doanh nghiệp được cấp giấy chứng nhận đủ điều kiện kinh doanh dịch vụ thẩm định giá về nhân sự là:',['Có ít nhất 03 người có thẻ thẩm định viên','Có ít nhất 05 người có thẻ thẩm định viên về giá đủ điều kiện đăng ký hành nghề tại doanh nghiệp','Có ít nhất 10 người có thẻ thẩm định viên','Có ít nhất 02 thẩm định viên và 1 kế toán'],1,'Điều 49: điều kiện chung là ít nhất 05 người có thẻ đủ điều kiện đăng ký hành nghề tại doanh nghiệp, cộng điều kiện riêng theo loại hình.','Luật Giá Đ.49');
q(1,'dntdg','Với công ty TNHH hai thành viên trở lên và công ty cổ phần, điều kiện riêng nào đúng?',['Ít nhất 02 thành viên góp vốn hoặc cổ đông là người có thẻ thẩm định viên đăng ký hành nghề tại doanh nghiệp','Tất cả thành viên phải có thẻ','Chỉ cần người đại diện theo pháp luật có thẻ','Không có điều kiện về vốn'],0,'Điều 49: ít nhất 02 thành viên/cổ đông có thẻ đăng ký hành nghề; tổng vốn góp của các thành viên là tổ chức không quá 35% vốn điều lệ; tổng vốn góp của thành viên/cổ đông là thẩm định viên phải chiếm trên 50% vốn điều lệ.','Luật Giá Đ.49');
q(1,'dntdg','Tổng phần vốn góp của các thành viên/cổ đông LÀ TỔ CHỨC trong doanh nghiệp thẩm định giá (TNHH 2 thành viên trở lên, cổ phần) không được vượt quá:',['25% vốn điều lệ','35% vốn điều lệ','49% vốn điều lệ','50% vốn điều lệ'],1,'Điều 49: không quá 35% vốn điều lệ, và người đại diện theo ủy quyền của tổ chức phải là người có thẻ đăng ký hành nghề tại doanh nghiệp. Cùng lúc, vốn của thành viên là thẩm định viên phải chiếm TRÊN 50%.','Luật Giá Đ.49');
q(1,'dntdg','Điều kiện nào đúng với người đại diện theo pháp luật, Giám đốc hoặc Tổng giám đốc của doanh nghiệp thẩm định giá (Điều 51)?',['Là thẩm định viên về giá tại doanh nghiệp đó và có từ đủ 36 tháng là thẩm định viên về giá','Chỉ cần có thẻ thẩm định viên','Có từ đủ 60 tháng làm việc tại cơ quan nhà nước','Không cần ghi tên trên Giấy chứng nhận đăng ký doanh nghiệp'],0,'Điều 51: ghi tên trên Giấy CN đăng ký doanh nghiệp; là thẩm định viên tại doanh nghiệp đó; đủ 36 tháng là thẩm định viên; duy trì điều kiện hành nghề; không thuộc trường hợp từng giữ vị trí này ở doanh nghiệp bị thu hồi giấy chứng nhận (12 tháng với lần 1, 60 tháng với lần 2).','Luật Giá Đ.51');
q(1,'dntdg','Khi doanh nghiệp thẩm định giá không còn đáp ứng một trong các điều kiện Điều 49, 50, doanh nghiệp phải làm gì?',['Báo cáo Bộ Tài chính trong 10 ngày và khắc phục trong tối đa 03 tháng kể từ ngày không đủ điều kiện','Dừng hoạt động ngay lập tức, không được khắc phục','Báo cáo trong 30 ngày và khắc phục trong 12 tháng','Không cần báo cáo'],0,'Điều 52 khoản 2: báo cáo Bộ Tài chính trong thời hạn 10 ngày; khắc phục trong tối đa 03 tháng.','Luật Giá Đ.52 k2');
q(1,'dntdg','Doanh nghiệp thẩm định giá bị ĐÌNH CHỈ kinh doanh dịch vụ thẩm định giá khi:',['Không đáp ứng một trong các điều kiện khoản 1 Điều 49 trong 03 tháng liên tục, hoặc phát hành chứng thư, báo cáo do người không phải thẩm định viên ký với vai trò thẩm định viên','Không phát hành chứng thư trong 12 tháng liên tục','Kê khai gian lận hồ sơ cấp giấy chứng nhận','Tự chấm dứt kinh doanh dịch vụ'],0,'Điều 54 khoản 1 là các trường hợp ĐÌNH CHỈ. Các phương án B, C, D thuộc khoản 2 (THU HỒI giấy chứng nhận). Cần phân biệt: đình chỉ là tạm dừng, có thể khắc phục; thu hồi là chấm dứt.','Luật Giá Đ.54');
q(1,'dntdg','Doanh nghiệp thẩm định giá bị THU HỒI giấy chứng nhận đủ điều kiện kinh doanh khi:',['Không phát hành chứng thư thẩm định giá, báo cáo thẩm định giá trong 12 tháng liên tục','Chậm báo cáo Bộ Tài chính 1 lần','Thay đổi trụ sở','Thay đổi người đại diện theo pháp luật'],0,'Điều 54 khoản 2 gồm: kê khai gian lận hồ sơ; không phát hành chứng thư/báo cáo 12 tháng liên tục; trong 60 ngày kể từ khi bị đình chỉ không khắc phục được; tự chấm dứt; bị thu hồi giấy đăng ký doanh nghiệp.','Luật Giá Đ.54 k2');
q(1,'dntdg','Nghĩa vụ nào sau đây là của doanh nghiệp thẩm định giá theo Điều 53?',['Mua bảo hiểm trách nhiệm nghề nghiệp hoặc trích lập dự phòng rủi ro nghề nghiệp','Bảo đảm khách hàng được lợi nhuận','Cung cấp miễn phí báo cáo cho cơ quan thuế','Chỉ tuyển thẩm định viên mới tốt nghiệp'],0,'Điều 53 khoản 2 yêu cầu doanh nghiệp: kiểm soát chất lượng báo cáo trước khi phát hành chứng thư, bồi thường thiệt hại nếu vi phạm, mua bảo hiểm trách nhiệm nghề nghiệp hoặc trích lập dự phòng rủi ro nghề nghiệp, quản lý thẩm định viên, lưu trữ hồ sơ.','Luật Giá Đ.53 k2');
q(1,'dntdg','Người đại diện theo pháp luật của doanh nghiệp thẩm định giá không còn là thẩm định viên tại doanh nghiệp trong thời gian khắc phục điều kiện. Doanh nghiệp được làm gì?',['Vẫn phát hành chứng thư bình thường','Không được phát hành chứng thư thẩm định giá, báo cáo thẩm định giá','Chỉ được phát hành báo cáo','Chỉ được nhận hợp đồng mới'],1,'Điều 52 khoản 3a: khi người đại diện theo pháp luật không còn là thẩm định viên tại doanh nghiệp hoặc không còn đáp ứng các điều kiện hành nghề, doanh nghiệp và chi nhánh không được phát hành chứng thư, báo cáo trong thời gian khắc phục.','Luật Giá Đ.52 k3a');

/* ===== HỘI ĐỒNG THẨM ĐỊNH GIÁ ===== */
q(1,'hdtdg','Số thành viên tối thiểu của hội đồng thẩm định giá là:',['02','03','05','07'],1,'Điều 60 khoản 1: tối thiểu 03 thành viên là cán bộ, công chức, viên chức, người lao động thuộc thẩm quyền quản lý của người thành lập hội đồng, trong đó có Chủ tịch.','Luật Giá Đ.60 k1');
q(1,'hdtdg','Điều kiện về chuyên môn của hội đồng thẩm định giá là gì?',['Mọi thành viên phải có thẻ thẩm định viên','Ít nhất 50% thành viên, bao gồm Chủ tịch, có ít nhất một trong các chứng nhận chuyên môn (bằng CĐ trở lên chuyên ngành giá/TĐG; thẻ thẩm định viên; chứng chỉ đào tạo nghiệp vụ TĐG; chứng chỉ bồi dưỡng TĐG nhà nước)','Chỉ Chủ tịch cần có chứng chỉ','Không có yêu cầu'],1,'Điều 60 khoản 2. Chú ý: yêu cầu là "ít nhất 50% thành viên, gồm cả Chủ tịch" và chứng nhận chuyên môn có bốn loại, không chỉ riêng thẻ thẩm định viên.','Luật Giá Đ.60 k2');
q(1,'hdtdg','Phiên họp của hội đồng thẩm định giá hợp lệ khi:',['Có mặt ít nhất 1/2 số thành viên','Có mặt ít nhất 2/3 số thành viên; hội đồng chỉ có 03 thành viên thì phải có mặt đủ 03','Có mặt toàn bộ thành viên trong mọi trường hợp','Có mặt Chủ tịch là đủ'],1,'Điều 60 khoản 3a: hội đồng làm việc theo nguyên tắc tập thể, quyết định theo đa số; phải có ít nhất 2/3 thành viên tham dự; riêng hội đồng 03 thành viên phải đủ 03. Thành viên vắng mặt phải có văn bản nêu lý do và ý kiến độc lập.','Luật Giá Đ.60 k3a');
q(1,'hdtdg','Hội đồng thẩm định giá biểu quyết có số ý kiến ngang nhau thì xử lý thế nào?',['Hoãn họp','Ý kiến của bên có biểu quyết của Chủ tịch hội đồng là ý kiến quyết định','Bốc thăm','Báo cáo cấp trên quyết định'],1,'Điều 60 khoản 3b. Thành viên không đồng ý với quyết định của hội đồng có quyền bảo lưu ý kiến.','Luật Giá Đ.60 k3b');
q(1,'hdtdg','Hoạt động thẩm định giá của Nhà nước KHÔNG áp dụng đối với:',['Tài sản công khi bán, thanh lý, cho thuê','Hàng hóa, dịch vụ thuộc Danh mục hàng hóa, dịch vụ do Nhà nước định giá','Mua sắm tài sản sử dụng vốn nhà nước','Liên doanh, liên kết bằng tài sản công'],1,'Điều 59: thẩm định giá của Nhà nước dùng làm một trong các cơ sở xem xét, phê duyệt giá khi bán, thanh lý, cho thuê, liên doanh, liên kết, chuyển giao tài sản công hoặc mua, đi thuê hàng hóa, dịch vụ, tài sản có sử dụng vốn nhà nước; nhưng không áp dụng với hàng hóa, dịch vụ thuộc danh mục Nhà nước định giá.','Luật Giá Đ.59');

/* ===== CHỨNG THƯ, BÁO CÁO, HỒ SƠ (TT 30/2024) ===== */
q(1,'chungthu','Thời gian hiệu lực tối đa của chứng thư thẩm định giá (Chuẩn mực theo TT 30/2024) là:',['03 tháng','06 tháng kể từ thời điểm phát hành','12 tháng','24 tháng'],1,'Chứng thư có hiệu lực từ ngày phát hành, thời hạn được xác định dựa trên đặc điểm pháp lý, kinh tế–kỹ thuật, biến động thị trường và mục đích thẩm định giá, nhưng tối đa không quá 06 tháng. Quy định tương tự áp dụng cho thông báo kết quả thẩm định giá của hội đồng.','TT 30/2024 Điều 7, Điều 10');
q(1,'chungthu','Thời hạn lưu trữ tối thiểu hồ sơ thẩm định giá là:',['03 năm','05 năm','10 năm kể từ ngày phát hành chứng thư','20 năm'],2,'Điều 12 Chuẩn mực về Hồ sơ TĐG: tối thiểu 10 năm kể từ ngày phát hành chứng thư tại doanh nghiệp hoặc chi nhánh phát hành. Hồ sơ lưu trữ gồm báo cáo, chứng thư, hợp đồng, tài liệu về tài sản và tài sản so sánh, biên bản khảo sát, ảnh chụp, tài liệu phân tích...','TT 30/2024 Điều 12');
q(1,'chungthu','Chữ ký trên chứng thư thẩm định giá theo Điều 55 Luật Giá gồm:',['Chỉ thẩm định viên','Chữ ký của thẩm định viên thực hiện thẩm định giá và chữ ký của người đại diện theo pháp luật (hoặc người đứng đầu chi nhánh), kèm đóng dấu','Chỉ người đại diện theo pháp luật','Khách hàng và thẩm định viên'],1,'Điều 55 khoản 1. Báo cáo thẩm định giá thì cần chữ ký thẩm định viên và PHÊ DUYỆT của người đại diện, và không thể tách rời chứng thư.','Luật Giá Đ.55');
q(1,'chungthu','Người đại diện theo pháp luật ủy quyền ký chứng thư thẩm định giá và duyệt báo cáo thì người được ủy quyền phải:',['Là người quản lý doanh nghiệp theo pháp luật về doanh nghiệp VÀ là thẩm định viên về giá tại doanh nghiệp','Chỉ cần là nhân viên doanh nghiệp','Là khách hàng','Là chuyên gia bên ngoài'],0,'Điều 55 khoản 3: được ủy quyền cho người quản lý doanh nghiệp, người được ủy quyền phải là thẩm định viên về giá tại doanh nghiệp.','Luật Giá Đ.55 k3');
q(1,'chungthu','Chứng thư và báo cáo thẩm định giá có giá trị sử dụng khi nào?',['Vô thời hạn','Chỉ trong thời hạn hiệu lực, đúng mục đích thẩm định giá, gắn với đúng thông tin và số lượng tài sản tại hợp đồng thẩm định giá','Trong 1 năm bất kể mục đích','Cho mọi tài sản cùng loại của khách hàng'],1,'Điều 55 khoản 4. Dùng cho mục đích khác, tài sản khác hoặc sau khi hết hạn thì chứng thư không còn giá trị.','Luật Giá Đ.55 k4');
q(1,'chungthu','Báo cáo thẩm định giá cần thể hiện điều gì về thông tin, số liệu sử dụng?',['Không cần dẫn nguồn','Được dẫn chiếu nguồn cụ thể và có thuyết minh, lập luận, phân tích về việc xác định giá trị','Chỉ cần ghi kết quả cuối cùng','Chỉ cần liệt kê tài sản so sánh'],1,'Điều 3 Chuẩn mực: báo cáo cung cấp thông tin thuyết minh, lập luận, phân tích; thông tin, số liệu phải dẫn chiếu nguồn cụ thể; có thể phát hành điện tử với chữ ký điện tử.','TT 30/2024 Điều 3');

/* ===== CƠ SỞ GIÁ TRỊ ===== */
q(1,'cosogt','Giá trị thị trường theo Chuẩn mực là:',['Giá bán thực tế đã ghi trong hợp đồng','Khoản tiền ước tính để tài sản có thể được giao dịch tại thời điểm thẩm định giá giữa người sẵn sàng mua và người sẵn sàng bán, trong giao dịch khách quan, độc lập, sau khi được tiếp thị đầy đủ, các bên hành động có hiểu biết, thận trọng, không bị ép buộc','Giá mà người bán mong muốn','Giá ghi sổ kế toán'],1,'Giá trị thị trường là mức giá ƯỚC TÍNH, không phải khoản tiền ấn định trước hay giá bán thực tế (Điều 5 k2). Gắn với thời điểm thẩm định giá cụ thể.','Chuẩn mực Cơ sở giá trị Điều 5');
q(1,'cosogt','Cơ sở giá trị nào phản ánh giá trị của tài sản đối với MỘT chủ sở hữu hoặc chủ sở hữu tiềm năng cụ thể cho hoạt động đầu tư cụ thể?',['Giá trị thị trường','Giá trị đầu tư','Giá trị bắt buộc phải bán','Giá trị thuê thị trường'],1,'Giá trị đầu tư mang tính đặc thù cho một đối tượng cụ thể, phản ánh lợi ích chủ sở hữu nhận được và thường dùng đo hiệu quả đầu tư (Điều 7).','Chuẩn mực Cơ sở giá trị Điều 7');
q(1,'cosogt','Giá trị bắt buộc phải bán phản ánh tình huống nào?',['Người bán bắt buộc phải bán trong thời gian hạn chế nên không tiếp thị đầy đủ, người mua có thể không kiểm tra đầy đủ tài sản','Người bán không muốn bán','Giao dịch giữa hai bên cụ thể thỏa thuận được lợi ích tương ứng','Tài sản cho thuê dài hạn'],0,'Điều 8: bắt buộc phải bán là tình huống giao dịch dự kiến vẫn diễn ra; giá đạt được phụ thuộc bản chất áp lực bán và lý do không thể tiếp thị đầy đủ. Phương án C là giá trị ngang bằng.','Chuẩn mực Cơ sở giá trị Điều 8, 9');
q(1,'cosogt','Giả thiết đặc biệt là gì và cần điều kiện nào?',['Giả thiết về thông tin còn hạn chế, không cần thông báo','Giả thiết về tình trạng tài sản khác thực tế tại thời điểm thẩm định giá, phù hợp mục đích; phải thông báo và có đồng thuận bằng văn bản của bên yêu cầu thẩm định giá','Giả thiết của thẩm định viên, không cần khách hàng biết','Giả thiết do cơ quan thuế đưa ra'],1,'Điều 10: giả thiết thường dùng cho thông tin hạn chế, không khắc phục được; GIẢ THIẾT ĐẶC BIỆT khác với thực tế nên bắt buộc thông báo và có văn bản đồng thuận, đồng thời phù hợp pháp luật. Nếu giả thiết đặc biệt làm thẩm định giá không khả thi thì loại bỏ.','Chuẩn mực Cơ sở giá trị Điều 10');
q(1,'cosogt','Vai trò của cơ sở giá trị trong thẩm định giá là:',['Chỉ để ghi trong chứng thư','Là nền tảng của hoạt động thẩm định giá; ảnh hưởng đến việc chọn phương pháp, thông tin đầu vào, giả thiết và quan điểm về giá trị; được xác định theo mục đích và tình huống giao dịch, sau khi trao đổi với bên yêu cầu','Do khách hàng tự chọn không cần trao đổi','Luôn là giá trị thị trường'],1,'Điều 4 khoản 2–3. Cơ sở giá trị gồm nhưng không giới hạn: giá trị thị trường, thuê thị trường, đầu tư, bắt buộc phải bán, ngang bằng; giá trị hợp lý theo pháp luật về lập báo cáo tài chính và IFRS.','Chuẩn mực Cơ sở giá trị Điều 4');

/* ===== THU THẬP & PHÂN TÍCH THÔNG TIN ===== */
q(1,'thongtin','Phương pháp so sánh áp dụng được khi thu thập tối thiểu bao nhiêu tài sản so sánh và điều kiện gì?',['01 tài sản','02 tài sản','03 tài sản từ các tổ chức, cá nhân khác nhau, giao dịch hoặc chào mua/bán gần thời điểm và địa điểm của tài sản thẩm định','10 tài sản'],2,'Điều 5 Chuẩn mực cách tiếp cận từ thị trường: ít nhất 03 tài sản so sánh từ các tổ chức, cá nhân khác nhau; thời điểm giao dịch hoặc chào mua/bán gần nhất nhưng không quá 24 tháng trước thời điểm thẩm định giá.','TT 32/2024 Điều 5');
q(1,'thongtin','Thời điểm giao dịch/chào giá của các tài sản so sánh không được xa hơn thời điểm thẩm định giá bao nhiêu (theo tài liệu CĐ4)?',['03 tháng','06 tháng','12 tháng','24 tháng'],3,'Theo hướng dẫn trong chuyên đề: ít nhất 03 tài sản so sánh, thời điểm giao dịch gần nhất nhưng không quá 24 tháng tính từ thời điểm thẩm định giá trở về trước. Lưu ý riêng kỹ thuật hao mòn "so sánh" yêu cầu ít nhất 02 tài sản trong không quá 01 năm.','CĐ4 slide; TT 32/2024');
q(1,'thongtin','Khi giá thị trường biến động giữa thời điểm giao dịch của tài sản so sánh và thời điểm thẩm định giá, thẩm định viên phải làm gì trước tiên?',['Bỏ qua','Điều chỉnh (tăng hoặc giảm) mức giá của tài sản so sánh về thời điểm thẩm định giá, rồi mới điều chỉnh theo các yếu tố so sánh','Chỉ điều chỉnh theo vị trí','Loại tài sản so sánh đó'],1,'Điều chỉnh về thời điểm thẩm định giá được làm TRƯỚC khi điều chỉnh các yếu tố so sánh khác. Đây là điều chỉnh yếu tố thời gian.','TT 32/2024 Điều 5 k3');
q(1,'thongtin','Thông tin tài sản so sánh thu thập trên Internet cần đáp ứng yêu cầu nào?',['Lấy từ bất kỳ diễn đàn nào','Phiếu thu thập dẫn chiếu cụ thể đường dẫn, lưu hình ảnh minh chứng; thông tin phải từ website chính thức của cơ quan, tổ chức hoạt động theo quy định pháp luật','Chỉ cần ghi tên website','Không cần lưu bằng chứng'],1,'Kết quả thu thập phải lập thành phiếu thu thập thông tin có chữ ký người thu thập; với báo giá chào mua/bán phải có tên, địa chỉ, mã số thuế (nếu có), đóng dấu, thời điểm cung cấp và hiệu lực báo giá.','TT 32/2024 Điều 6');
q(1,'thongtin','Phân tích "sử dụng tốt nhất và có hiệu quả nhất" theo Chuẩn mực chỉ áp dụng với loại tài sản nào?',['Mọi tài sản','Bất động sản','Máy, thiết bị','Tài sản vô hình'],1,'Điều 8 Chuẩn mực về thu thập, phân tích thông tin: nội dung phân tích sử dụng tốt nhất và hiệu quả nhất chỉ áp dụng đối với bất động sản. Đó là việc sử dụng phù hợp pháp luật, khả thi về vật chất, kỹ thuật và mang lại hiệu quả kinh tế cao nhất.','TT 31/2024 Điều 8');
q(1,'thongtin','Hồ sơ do bên yêu cầu thẩm định giá cung cấp có điểm khác với kết quả khảo sát hiện trạng tài sản. Thẩm định viên cần:',['Dùng số liệu của khách hàng','Dùng số liệu khảo sát và không báo cho ai','Kịp thời trao đổi với bên yêu cầu để bổ sung hoặc làm rõ, bảo đảm khách quan, nghiêm cấm tác động làm ảnh hưởng đến giá trị tài sản','Từ chối vĩnh viễn hợp đồng'],2,'Điều 7 Chuẩn mực: khi có sai khác hoặc hồ sơ không đầy đủ phải kịp thời trao đổi để bổ sung, làm rõ; quá trình này phải bảo đảm tính khách quan và nghiêm cấm mọi hành vi tác động ảnh hưởng.','TT 31/2024 Điều 7');
q(1,'thongtin','Tổng giá trị điều chỉnh THUẦN và GỘP khác nhau thế nào?',['Thuần cộng trị tuyệt đối, gộp tính cả dấu','Thuần là tổng mức điều chỉnh có tính dấu (+/−); gộp là tổng giá trị tuyệt đối của các lần điều chỉnh','Hai khái niệm đồng nghĩa','Thuần chỉ tính điều chỉnh tăng'],1,'Điều 3 Chuẩn mực cách tiếp cận từ thị trường: thuần có tính dấu âm/dương (có thể bù trừ); gộp là tổng giá trị tuyệt đối. Tài sản so sánh tốt thường có gộp nhỏ, thuần nhỏ, ít lần điều chỉnh.','TT 32/2024 Điều 3');

/* ===== PHÁP LUẬT DOANH NGHIỆP ===== */
q(1,'phapluatdn','Công ty trách nhiệm hữu hạn hai thành viên trở lên có tối đa bao nhiêu thành viên?',['30','50','100','Không giới hạn'],1,'Công ty TNHH 2 thành viên trở lên: số lượng không quá 50, có tư cách pháp nhân, không được phát hành cổ phần, trách nhiệm hữu hạn trong phạm vi vốn góp.','CĐ1A Pháp luật doanh nghiệp');
q(1,'phapluatdn','Công ty cổ phần có số cổ đông tối thiểu là:',['01','02','03','07'],2,'Cổ đông là tổ chức hoặc cá nhân, số lượng tối thiểu là 03, không hạn chế tối đa; vốn chia thành cổ phần bằng nhau; được quyền phát hành cổ phần, chứng khoán.','CĐ1A Pháp luật doanh nghiệp');
q(1,'phapluatdn','Loại hình doanh nghiệp nào KHÔNG có tư cách pháp nhân?',['Công ty TNHH một thành viên','Công ty cổ phần','Công ty hợp danh','Doanh nghiệp tư nhân'],3,'Doanh nghiệp tư nhân: một cá nhân làm chủ, không có tư cách pháp nhân, chủ chịu trách nhiệm vô hạn, không được phát hành chứng khoán. Công ty hợp danh VẪN là pháp nhân (có ít nhất 02 thành viên hợp danh là cá nhân chịu trách nhiệm vô hạn).','CĐ1A Pháp luật doanh nghiệp');
q(1,'phapluatdn','Thành viên hợp danh trong công ty hợp danh chịu trách nhiệm như thế nào?',['Hữu hạn trong phạm vi vốn góp','Vô hạn bằng toàn bộ tài sản và có quyền đại diện cho công ty','Không chịu trách nhiệm','Chỉ chịu trách nhiệm theo thỏa thuận'],1,'Thành viên hợp danh (ít nhất 2, là cá nhân) chịu trách nhiệm vô hạn, có quyền đại diện; thành viên góp vốn (nếu có) chịu trách nhiệm hữu hạn. Công ty hợp danh không phát hành chứng khoán.','CĐ1A Pháp luật doanh nghiệp');
q(1,'phapluatdn','Vốn pháp định là gì?',['Vốn các thành viên đã góp','Mức vốn tối thiểu phải có theo quy định pháp luật để thành lập doanh nghiệp ở một số ngành, lĩnh vực nhất định','Vốn vay ngân hàng','Vốn tự có của doanh nghiệp'],1,'Vốn điều lệ là số vốn thành viên, cổ đông đã góp hoặc cam kết góp trong một thời hạn nhất định, ghi vào Điều lệ (doanh nghiệp tư nhân gọi là vốn đăng ký). Vốn pháp định là mức tối thiểu luật quy định cho ngành đặc thù.','CĐ1A Pháp luật doanh nghiệp');
q(1,'phapluatdn','Cổ đông sáng lập bị hạn chế chuyển nhượng cổ phần phổ thông cho người không phải cổ đông sáng lập trong bao lâu kể từ khi công ty được cấp Giấy chứng nhận đăng ký doanh nghiệp?',['01 năm','02 năm','03 năm','05 năm'],2,'Theo tài liệu chuyên đề: cổ đông sáng lập không được tự do chuyển nhượng ra bên ngoài trong vòng 03 năm kể từ khi thành lập. Khi phát hành cổ phần riêng lẻ, Luật Chứng khoán hạn chế chuyển nhượng 01 năm.','CĐ1A Pháp luật doanh nghiệp');
q(1,'phapluatdn','Ai KHÔNG có quyền thành lập, góp vốn, mua cổ phần vào doanh nghiệp theo hướng dẫn trong chuyên đề (đối tượng bị cấm)?',['Cán bộ, công chức, quân nhân ở diện bị cấm; người bị hạn chế hoặc mất năng lực hành vi; người đang bị phạt tù hoặc bị cấm kinh doanh','Mọi cá nhân từ 18 tuổi','Người nước ngoài','Doanh nhân tư nhân'],0,'Chuyên đề nêu nhóm bị cấm thành lập doanh nghiệp: cơ quan nhà nước, đơn vị vũ trang; cán bộ, công chức, quân nhân; lãnh đạo doanh nghiệp 100% vốn nhà nước; người hạn chế hoặc mất năng lực hành vi; người bị phạt tù hoặc cấm kinh doanh; một số trường hợp khác.','CĐ1A Pháp luật doanh nghiệp');
q(1,'phapluatdn','Luật nào là cơ sở pháp lý về phá sản doanh nghiệp, có hiệu lực từ 01/01/2015?',['Luật Phá sản 2014','Luật Doanh nghiệp 2014','Bộ luật Dân sự 2015','Luật Đầu tư 2014'],0,'Phá sản là thủ tục trả nợ tập thể và chấm dứt hoạt động của doanh nghiệp, theo Luật Phá sản 2014 (hiệu lực 01/01/2015). Chủ nợ không bảo đảm hoặc bảo đảm một phần, đại diện doanh nghiệp, cổ đông đại diện 20% cổ phần phổ thông… có quyền nộp đơn.','CĐ1A Pháp luật doanh nghiệp');

/* ===== THUẾ ===== */
q(1,'thue','Đặc trưng cơ bản của thuế KHÔNG gồm:',['Tính bắt buộc','Tính không hoàn trả trực tiếp','Tính đối giá, đối khoản với người nộp','Do Quốc hội quyết định dưới hình thức luật'],2,'Thuế có tính bắt buộc, không hoàn trả trực tiếp, KHÔNG đối giá và không đối khoản (người nộp không nhận lại khoản tương ứng); do Quốc hội quyết định qua luật.','CĐ1A Pháp luật thuế');
q(1,'thue','Kiểm tra thuế tại trụ sở người nộp thuế kéo dài tối đa bao lâu?',['Không quá 5 ngày, gia hạn một lần không quá 5 ngày','Không quá 30 ngày','Không quá 10 ngày, không gia hạn','Không giới hạn'],0,'Theo tài liệu: kiểm tra tại trụ sở người nộp thuế không quá 5 ngày, gia hạn một lần không quá 5 ngày. Thanh tra thuế tối đa 30 ngày, gia hạn không quá 30 ngày.','CĐ1A Pháp luật thuế');
q(1,'thue','Thanh tra thuế khác kiểm tra thuế ở điểm nào?',['Thanh tra xác minh CÓ hay KHÔNG CÓ vi phạm pháp luật thuế; kiểm tra đánh giá mức độ chấp hành','Hai hoạt động giống nhau','Kiểm tra chỉ do hải quan thực hiện','Thanh tra không cần quyết định'],0,'Kiểm tra thuế là hoạt động quản lý nhà nước đánh giá mức độ chấp hành pháp luật thuế. Thanh tra thuế xác minh có/không có vi phạm; quy trình: ra quyết định, thanh tra, kết luận, giao quyết định. Người nộp thuế có quyền từ chối nếu không có quyết định.','CĐ1A Pháp luật thuế');
q(1,'thue','Cơ chế quản lý thuế hiện hành dựa trên nguyên tắc nào?',['Cơ quan thuế ấn định thuế cho mọi doanh nghiệp','Tự khai, tự nộp: doanh nghiệp chủ động xác định số thuế trong thời hạn luật định, cơ quan thuế tập trung giám sát doanh nghiệp có dấu hiệu vi phạm','Chỉ nộp thuế khi cơ quan thuế thông báo','Nộp thuế một lần cho cả năm'],1,'Cơ chế tự khai, tự nộp đảm bảo chủ động cho doanh nghiệp và khả năng giám sát tập trung. Cơ sở pháp lý: Luật Quản lý thuế 2019.','CĐ1A Pháp luật thuế');
q(1,'thue','Chuyển giá và sử dụng "thiên đường thuế" là biểu hiện của hành vi nào được chuyên đề nêu?',['Trốn thuế (gian lận để giảm hoặc không nộp thuế)','Tránh thuế (chọn mức thuế thấp để nộp thay vì mức cao hơn) trong thực tế','Miễn thuế','Hoàn thuế'],1,'Chuyên đề gắn chuyển giá, thiên đường thuế với tránh thuế; giải pháp gồm quản lý giá và định mức chi phí, cơ chế thỏa thuận trước về phương pháp xác định giá tính thuế (APA). Trốn thuế là gian lận làm giảm hoặc không nộp thuế.','CĐ1A Pháp luật thuế');

/* ===== HỢP ĐỒNG ===== */
q(1,'hopdong','Thời hiệu yêu cầu Tòa án tuyên bố giao dịch (hợp đồng) vô hiệu trong các trường hợp thông thường được nêu trong tài liệu là:',['6 tháng','1 năm','2 năm kể từ ngày giao dịch được xác lập','Không hạn chế'],2,'Theo tài liệu: thời hiệu đề nghị tuyên vô hiệu 02 năm kể từ ngày giao dịch được xác lập; một số trường hợp không hạn chế thời hiệu (vi phạm điều cấm, trái đạo đức, giả tạo…). Hợp đồng chỉ vô hiệu khi có tuyên bố của Tòa án hoặc trọng tài.','CĐ1A Hợp đồng');
q(1,'hopdong','Trọng tài thương mại có thể giải quyết tranh chấp khi nào?',['Mọi tranh chấp, kể cả khi không có thỏa thuận','Khi các bên có thỏa thuận trọng tài; phán quyết trọng tài là chung thẩm, giải quyết một lần','Chỉ khi Tòa án chuyển sang','Chỉ với tranh chấp bất động sản'],1,'Điều kiện bắt buộc là có thỏa thuận trọng tài. Trọng tài giải quyết một lần (chung thẩm), khác với Tòa án có các cấp xét xử. Thương lượng, hòa giải là phương thức đầu tiên, không bắt buộc có thỏa thuận.','CĐ1A Hợp đồng');
q(1,'hopdong','Hậu quả của hợp đồng vô hiệu nói chung là:',['Hợp đồng vẫn có hiệu lực đối với bên ngay tình','Các bên khôi phục tình trạng ban đầu, hoàn trả cho nhau những gì đã nhận; bên có lỗi phải bồi thường thiệt hại','Chỉ bên có lỗi phải hoàn trả','Không có hậu quả pháp lý'],1,'Giao dịch vô hiệu không làm phát sinh quyền, nghĩa vụ từ thời điểm xác lập: các bên hoàn trả, bên có lỗi bồi thường. Khi áp dụng cho hợp đồng thẩm định giá, chứng thư lập trên hợp đồng vô hiệu không có giá trị.','CĐ1A Hợp đồng');

/* ===== SHTT ===== */
q(1,'shtt','Quyền tác giả phát sinh từ khi nào?',['Từ khi được cấp Giấy chứng nhận đăng ký quyền tác giả','Từ khi tác phẩm được sáng tạo và thể hiện dưới một hình thức vật chất nhất định, không phụ thuộc đã công bố hay đăng ký hay chưa','Từ khi tác phẩm được công bố','Từ khi tác giả qua đời'],1,'Quyền tác giả phát sinh tự động từ khi tác phẩm được sáng tạo và thể hiện; đăng ký chỉ là căn cứ chứng minh. Khác với quyền sở hữu công nghiệp.','CĐ1A SHTT; Luật SHTT');
q(1,'shtt','Quyền sở hữu công nghiệp đối với sáng chế, kiểu dáng công nghiệp, nhãn hiệu được xác lập trên cơ sở nào?',['Tự động từ khi sáng tạo','Quyết định cấp văn bằng bảo hộ của cơ quan nhà nước có thẩm quyền (nhãn hiệu nổi tiếng, tên thương mại, bí mật kinh doanh có cơ chế riêng)','Chỉ cần nộp đơn','Thỏa thuận giữa các bên'],1,'Quyền sở hữu công nghiệp xác lập theo văn bản bảo hộ (Bằng độc quyền sáng chế, Giấy chứng nhận đăng ký kiểu dáng, nhãn hiệu…). Quyền đối với giống cây trồng xác lập theo Bằng bảo hộ giống cây trồng. Điều này quan trọng với thẩm định giá tài sản vô hình vì tài sản phải được pháp luật công nhận và bảo vệ.','CĐ1A SHTT; Luật SHTT');
q(1,'shtt','Luật Sở hữu trí tuệ hiện hành được ban hành năm 2005 và đã được sửa đổi, bổ sung vào các năm nào?',['2009, 2019, 2022','2010, 2015, 2020','2012, 2018','Chưa sửa đổi lần nào'],0,'Luật Sở hữu trí tuệ 2005, sửa đổi bổ sung các năm 2009, 2019 và 2022 (theo bài giảng). Kiểm tra bản mới nhất khi ôn vì luật có thể tiếp tục được sửa.','CĐ1A SHTT');

/* ===== NGUYÊN LÝ ===== */
q(1,'nguyenly','Tài sản thẩm định giá gồm bốn loại cơ bản nào?',['Bất động sản; động sản; doanh nghiệp; tài sản vô hình','Đất đai; nhà ở; máy móc; hàng hóa','Tài sản cố định; tài sản lưu động; đầu tư tài chính; hàng tồn kho','Bất động sản; hàng hóa; dịch vụ; quyền sử dụng đất'],0,'Theo chuyên đề: bốn loại cơ bản là bất động sản, động sản, doanh nghiệp, tài sản vô hình. Gắn với đó có TĐG bất động sản; TĐG động sản (máy thiết bị, tài sản vô hình, động sản khác); TĐG doanh nghiệp.','CĐ2 mục 2.2.1.3');
q(1,'nguyenly','Có bao nhiêu Chuẩn mực áp dụng chung và những chuẩn mực này nằm trong phạm vi học và thi phần pháp luật–nguyên lý?',['8 chuẩn mực áp dụng chung (đạo đức; phạm vi công việc; cơ sở giá trị; hồ sơ; thu thập và phân tích thông tin; ba cách tiếp cận thị trường, chi phí, thu nhập)','3 chuẩn mực','11 chuẩn mực đều thi như nhau','5 chuẩn mực'],0,'Tài liệu nêu 11 chuẩn mực, chia nhóm áp dụng chung (8) và nhóm áp dụng cho tài sản cụ thể (doanh nghiệp, tài sản vô hình, bất động sản). Theo hướng dẫn, "các chuẩn mực áp dụng chung" là nội dung học và thi ở phần này. Lưu ý số lượng chuẩn mực có thể thay đổi khi sửa đổi.','CĐ2 mục 2.2.3');
q(1,'nguyenly','Thẩm định giá cùng một tài sản, cùng thời điểm nhưng cho mục đích khác nhau thì kết quả:',['Luôn bằng nhau','Có thể khác nhau, vì mục đích quyết định cơ sở giá trị và cách tiếp cận','Chỉ khác nếu đổi thẩm định viên','Phải bằng giá niêm yết'],1,'Mục đích như mua bán, thế chấp, bảo hiểm, tính thuế, thanh lý, đầu tư… dẫn đến cơ sở giá trị khác và vì vậy kết quả khác (ví dụ giá trị thị trường khác giá trị bắt buộc phải bán).','CĐ2 mục 2.2.1.4');
q(1,'nguyenly','Đặc trưng nào của hoạt động thẩm định giá được nêu trong chuyên đề?',['Chỉ dùng đánh giá định tính','Nghiên cứu có lựa chọn một khu vực thị trường, một loại tài sản; dùng nhiều dữ liệu; dùng kỹ thuật phân tích định lượng; đòi hỏi kiến thức đa ngành; cung cấp ý kiến về giá trị dựa trên bằng chứng thị trường','Không cần dữ liệu','Một cuộc thẩm định có thể gồm mọi loại tài sản ở mọi thị trường'],1,'Năm đặc trưng chính theo chuyên đề; thẩm định viên không thể thực hiện một cuộc thẩm định cho nhiều loại tài sản ở nhiều khu vực thị trường khác nhau.','CĐ2 mục 2.2.1.2');
q(1,'nguyenly','Tổng giá cả của toàn bộ hàng hóa trong nền kinh tế, khi tiền tệ không đổi giá trị, so với tổng giá trị thì:',['Luôn cao hơn','Luôn thấp hơn','Bằng nhau: giá cả hàng hóa nhóm này lệch cao hơn giá trị thì nhóm khác lệch thấp hơn','Không liên quan'],2,'Quy luật giá trị: giá cả xoay quanh giá trị; do quỹ mua hàng trong một thời gian xác định, khi giá nhóm hàng này tách rời cao hơn giá trị thì nhóm khác phải thấp hơn, nên tổng giá cả bằng tổng giá trị.','CĐ2 mục 2.1');
/* ================= MÔN 2: THẨM ĐỊNH GIÁ BẤT ĐỘNG SẢN ================= */
/* ===== TỔNG QUAN BĐS & THỊ TRƯỜNG ===== */
q(2,'bds_tq','Theo khoản 1 Điều 107 Bộ luật Dân sự 2015, bất động sản gồm:',['Đất đai; nhà, công trình xây dựng gắn liền với đất đai; tài sản gắn liền với đất đai, nhà, công trình xây dựng; các tài sản khác gắn liền với đất đai; tài sản khác theo quy định của pháp luật','Chỉ đất đai','Đất đai và máy móc đặt trong nhà xưởng','Chỉ nhà ở và công trình thương mại'],0,'Danh mục gồm 5 nhóm. Máy, thiết bị chỉ là bất động sản khi thuộc "tài sản gắn liền với đất đai, nhà, công trình xây dựng" theo quy định, còn thông thường máy thiết bị là động sản.','CĐ4 Phần I; BLDS 2015 Đ.107');
q(2,'bds_tq','Đặc điểm nào KHÔNG phải của bất động sản?',['Tính cố định về vị trí','Tính khan hiếm','Tính thanh khoản cao, dễ chuyển đổi thành tiền','Tính lâu bền'],2,'Chuyên đề nêu 8 đặc điểm: khan hiếm, cố định về vị trí, thanh khoản kém, lâu bền, giá trị lớn, khác biệt, thích ứng, ảnh hưởng lẫn nhau. Bất động sản có tính thanh khoản KÉM.','CĐ4 mục 1.1.2');
q(2,'bds_tq','Đặc điểm nào sau đây là của thị trường bất động sản?',['Là thị trường cạnh tranh hoàn hảo','Cung và cầu ít co giãn; mang tính khu vực; cần các tổ chức trung gian; dạng điển hình của thị trường không hoàn hảo; chịu sự kiểm soát của Nhà nước','Giá hoàn toàn thống nhất trên toàn quốc','Hàng hóa và địa điểm giao dịch luôn ở cùng một nơi'],1,'Thị trường BĐS là dạng điển hình của thị trường không hoàn hảo; giao dịch các quyền và lợi ích hợp pháp liên quan đến BĐS; hàng hóa và địa điểm giao dịch tách biệt vì BĐS cố định.','CĐ4 mục 1.2.2');
q(2,'bds_tq','Thẩm định giá bất động sản được hiểu là:',['Hoạt động tư vấn xác định giá trị của bất động sản tại một địa điểm, thời điểm, phục vụ mục đích nhất định, do doanh nghiệp hoặc hội đồng thẩm định giá thực hiện theo Chuẩn mực','Hoạt động định giá đất của Nhà nước','Hoạt động môi giới','Hoạt động xây dựng bảng giá đất'],0,'Cùng khái niệm tại Luật Giá, áp dụng cho đối tượng là bất động sản. Phạm vi công việc: trao đổi với bên yêu cầu, lập kế hoạch, thu thập và phân tích thông tin, chọn và áp dụng phương pháp, xác định giá trị, lập báo cáo và chứng thư.','CĐ4 Phần II');
q(2,'bds_tq','Các phương pháp thẩm định giá bất động sản gồm (theo cách phân nhóm của chuyên đề):',['So sánh; chi phí thay thế, chi phí tái tạo; vốn hóa trực tiếp, dòng tiền chiết khấu; thặng dư','Chỉ so sánh và chi phí','Chỉ vốn hóa trực tiếp','So sánh, thặng dư, bình quân gia quyền'],0,'Cách tiếp cận thị trường → phương pháp so sánh; cách tiếp cận chi phí → chi phí thay thế, chi phí tái tạo; cách tiếp cận thu nhập → vốn hóa trực tiếp, dòng tiền chiết khấu; cách tiếp cận kết hợp → phương pháp thặng dư (dành cho BĐS có tiềm năng phát triển).','CĐ4 Phần III');

/* ===== SO SÁNH ===== */
q(2,'sosanh','Nguyên tắc điều chỉnh trong phương pháp so sánh theo giáo trình là:',['Lấy tài sản so sánh làm chuẩn; yếu tố tài sản mục tiêu không có thì trừ','Lấy BĐS mục tiêu (cần thẩm định) làm chuẩn; yếu tố có ở BĐS mục tiêu mà không có ở BĐS so sánh thì cộng thêm (+), và ngược lại','Chỉ điều chỉnh tăng','Không cần điều chỉnh khi có từ 3 tài sản'],1,'Điều chỉnh để đưa tài sản so sánh "về" tài sản thẩm định: so sánh kém hơn mục tiêu → điều chỉnh tăng; so sánh tốt hơn → giảm. Mỗi điều chỉnh phải có chứng cứ thị trường.','CĐ4 Bước 3 phương pháp so sánh');
q(2,'sosanh','Thứ tự điều chỉnh đúng trong phương pháp so sánh là:',['Kinh tế–kỹ thuật trước, pháp lý sau','Nhóm pháp lý và tình trạng giao dịch trước; sau đó kinh tế–kỹ thuật (điều chỉnh số tiền tuyệt đối trước, tỷ lệ % sau); giá sau khi điều chỉnh tuyệt đối làm cơ sở điều chỉnh %','Theo thứ tự bất kỳ','Điều chỉnh tỷ lệ % trước rồi cộng tiền sau'],1,'Vì điều chỉnh pháp lý và điều kiện giao dịch (thanh toán, chi phí hợp thức hóa) thường là số tiền cụ thể, làm trước để có "giá cơ sở" chuẩn rồi mới áp dụng các tỷ lệ % về vị trí, hình dáng, hạ tầng...','CĐ4 Bước 3');
q(2,'sosanh','Nguyên tắc khống chế khi điều chỉnh: chênh lệch giữa mỗi mức giá chỉ dẫn với giá trị trung bình của các mức giá chỉ dẫn:',['Không quá 5%','Không quá 10%','Không quá 15%','Không quá 30%'],2,'Nếu một mức giá chỉ dẫn lệch quá 15% so với trung bình thì tài sản so sánh đó kém tin cậy: cần rà lại điều chỉnh hoặc loại bỏ.','CĐ4 nguyên tắc khống chế');
q(2,'sosanh','Khi có ba mức giá chỉ dẫn, tiêu chí nào giúp chọn mức giá làm đại diện?',['Chọn mức cao nhất','Phân tích chất lượng thông tin và các chỉ tiêu: tổng điều chỉnh gộp nhỏ nhất, số lần điều chỉnh ít nhất, biên độ điều chỉnh nhỏ nhất, tổng điều chỉnh thuần nhỏ nhất','Chọn tài sản gần nhất về thời gian','Luôn lấy trung bình cộng'],1,'Tài sản được điều chỉnh ít và nhỏ thì giống tài sản thẩm định nhất nên mức giá chỉ dẫn đáng tin cậy nhất. Trung bình cộng chỉ hợp lý khi chất lượng thông tin ngang nhau và các chỉ tiêu chênh lệch không đáng kể.','CĐ4 Bước 5; TT 32/2024');
q(2,'sosanh','Giá đất mặt ngõ 8m bằng 90% giá đất mặt ngõ 10m. Tài sản thẩm định ở ngõ 10m, tài sản so sánh ở ngõ 8m. Tỷ lệ điều chỉnh (lấy tài sản thẩm định làm chuẩn) là:',['+10%','+11,11%','−10%','−9,09%'],1,'Điều chỉnh = giá trị mục tiêu ÷ giá trị so sánh − 1 = 100/90 − 1 = +11,11% (không phải +10%). Cẩn thận cách đọc đề: nếu đề nói "ngõ 10m CAO HƠN ngõ 8m 10%" thì hệ số là 1,10 và so sánh ngõ 8m được điều chỉnh +10%; nếu đề nói ngõ 8m BẰNG 90% ngõ 10m thì phải chia: 100/90. Giáo trình dùng cách tỷ lệ % rồi lấy 100/hệ số − 1 cho mọi yếu tố.','BÀI TẬP VẬN DỤNG BĐS, so sánh bài 1');
q(2,'sosanh','Thông tin về tài sản so sánh thu được từ giao dịch thanh toán chậm 40% sau một năm (lãi suất vay 20%/năm). Để quy về thanh toán ngay một lần, cần:',['Cộng thêm lãi vay vào giá','Chiết khấu phần trả chậm về hiện tại, tính giá tương đương thanh toán ngay','Bỏ qua vì không ảnh hưởng giá','Giảm 20% giá bán'],1,'Điều kiện thanh toán là yếu tố điều chỉnh số tiền tuyệt đối: giá quy đổi = phần trả ngay + phần trả chậm / (1 + lãi suất)^t. Ví dụ giá 22 trđ/m², trả 60% ngay, 40% sau 1 năm, lãi 20%: 22×0,6 + 22×0,4/1,2 = 20,53 trđ/m² (điều chỉnh −1,47).','BÀI TẬP VẬN DỤNG BĐS, bài 1');
q(2,'sosanh','"Phương pháp chiết trừ" trong thẩm định giá BĐS dùng để làm gì?',['Ước tính giá đất bằng cách lấy giá bán cả bất động sản trừ đi giá trị công trình xây dựng còn lại trên đất','Ước tính giá trị công trình bằng cách lấy giá đất trừ đi giá bán','Tính thuế sử dụng đất','Ước tính lãi vay'],0,'Giá đất = giá bán (đất + công trình) − giá trị còn lại của công trình (chi phí xây mới × tỷ lệ chất lượng còn lại). Sau đó quy về đơn giá /m² và điều chỉnh các yếu tố so sánh. Dùng khi không có giao dịch đất trống tương tự.','CĐ4; Đề thi 2017 câu 2a');
q(2,'sosanh','Nhược điểm của phương pháp so sánh là:',['Quá phức tạp về kỹ thuật','Chất lượng thông tin giao dịch tương tự không tốt sẽ ảnh hưởng kết quả; thông tin mang tính lịch sử; chứa yếu tố chủ quan','Không được cơ quan pháp lý công nhận','Chỉ dùng được cho máy móc'],1,'Ưu điểm: ít khó khăn kỹ thuật, dựa trên giá thị trường nên được công nhận rộng rãi, là cơ sở cho nhiều phương pháp khác. Nhược điểm như trên.','CĐ4 mục 3.1.3');

/* ===== CHI PHÍ ===== */
q(2,'chiphi','Chi phí tái tạo khác chi phí thay thế ở điểm nào?',['Tái tạo tạo ra tài sản giống hệt tài sản thẩm định; thay thế tạo ra tài sản có chức năng, công dụng tương tự bằng công nghệ, vật liệu mới hơn','Hai khái niệm giống nhau','Tái tạo luôn thấp hơn thay thế','Tái tạo chỉ tính vật liệu'],0,'Chi phí tái tạo: tạo ra tài sản giống hệt khi mới 100% tại thời điểm thẩm định giá. Chi phí thay thế: tạo ra tài sản thay thế mới 100%. Công trình mới thì chi phí thay thế bằng chi phí tái tạo.','CĐ4 mục 3.2.2.1');
q(2,'chiphi','Công thức của cách tiếp cận chi phí đối với bất động sản (đất có công trình) là:',['Giá trị đất + chi phí tái tạo (hoặc thay thế) của công trình − tổng giá trị hao mòn','Chi phí xây dựng + lợi nhuận','Giá đất × diện tích','Doanh thu − chi phí'],0,'Năm bước: (1) ước tính giá đất như đất trống, theo sử dụng tốt nhất và hiệu quả nhất; (2) chi phí xây dựng lại công trình; (3) ước tính hao mòn tích lũy; (4) giá trị hiện tại của công trình = (2) − (3); (5) cộng (1) và (4).','CĐ4 mục 3.2.2');
q(2,'chiphi','Ba loại hao mòn trong cách tiếp cận chi phí là:',['Hao mòn vật lý, hao mòn chức năng, hao mòn ngoại biên (kinh tế, vị trí)','Hao mòn hữu hình, vô hình, tài chính','Hao mòn cơ học, nhiệt, điện','Hao mòn cố định, lưu động, thị trường'],0,'Mỗi loại lại chia hao mòn có thể khắc phục được và không thể khắc phục được (ngoại biên thường không khắc phục được). Cần tránh tính trùng giữa các loại hao mòn.','CĐ4 mục 3.2.2.2');
q(2,'chiphi','Hao mòn chức năng do chi phí vận hành cao được ước tính bằng cách nào?',['Chi phí tái tạo − chi phí thay thế','Giá trị hiện tại của chênh lệch chi phí vận hành hàng năm (sau thuế) trong tuổi đời kinh tế còn lại','Chi phí khắc phục − thu thanh lý','Vốn hóa thu nhập mất đi'],1,'Hao mòn chức năng do chi phí vốn cao (không khắc phục được) = chi phí tái tạo − chi phí thay thế. Hao mòn chức năng khắc phục được = chi phí khắc phục − thu thanh lý. Hao mòn do chi phí vận hành cao = hiện giá của chênh lệch vận hành, trừ tác động thuế.','CĐ4 & CĐ5, phần hao mòn chức năng');
q(2,'chiphi','Hao mòn ngoại biên được ước tính bằng cách nào?',['Phân tích thông tin thị trường của tài sản tương tự đã giao dịch, hoặc vốn hóa trực tiếp thu nhập bị mất do tác động bên ngoài','Lấy chi phí khắc phục','Dùng tuổi đời hiệu quả','Dùng tỷ lệ kết cấu chính'],0,'Nguyên nhân ngoại biên: các nhân tố bên ngoài tài sản như ô nhiễm, thay đổi quy hoạch, suy giảm thị trường, chính sách thuế. Ví dụ đề bài hao mòn kinh tế dây chuyền bia: thu nhập mất đi hàng năm × hệ số hiện giá niên kim.','CĐ4 mục 3.2.2.2c');
q(2,'chiphi','Trong cách tiếp cận chi phí, tổng giá trị hao mòn theo kỹ thuật "tuổi đời" được tính theo tỷ lệ nào?',['Tuổi đời hiệu quả / tuổi đời kinh tế (hoặc vật lý)','Tuổi đời thực tế / tuổi đời hiệu quả','Tuổi đời kinh tế / tuổi đời hiệu quả','Tuổi đời còn lại / tuổi đời thực tế'],0,'Tỷ lệ hao mòn = tuổi đời hiệu quả ÷ tuổi đời kinh tế (hoặc vật lý) × 100%. Tuổi đời hiệu quả phản ánh tình trạng thực tế, phụ thuộc bảo dưỡng; có thể lớn hơn hoặc nhỏ hơn tuổi đời thực tế.','CĐ4/CĐ5; TT 32/2024 Điều 11');
q(2,'chiphi','Chất lượng còn lại của công trình: móng có tỷ trọng 8% còn 68%, tường 18% còn 56%, sàn 16% còn 64%, mái 14% còn 56%. Chất lượng còn lại bình quân gia quyền là:',['56%','60%','64%','68%'],1,'(68×8 + 56×18 + 64×16 + 56×14) / (8+18+16+14) = (544+1008+1024+784)/56 = 3360/56 = 60%. Phải chia cho TỔNG tỷ trọng các kết cấu được xét.','BÀI TẬP VẬN DỤNG BĐS, chi phí bài 2');
q(2,'chiphi','Cách tiếp cận chi phí thích hợp nhất trong trường hợp nào?',['Bất động sản có dòng thu nhập ổn định và nhiều giao dịch tương tự','Bất động sản đặc thù không có giao dịch, không dự báo được dòng tiền; thẩm định giá cho mục đích bảo hiểm, đấu thầu; hoặc để kiểm tra các phương pháp khác','Mọi trường hợp luôn ưu tiên','Chỉ đất trống'],1,'Hạn chế: chi phí không phải lúc nào cũng bằng giá trị; cách tiếp cận cộng tới nhưng tổng các bộ phận chưa chắc bằng giá trị toàn bộ; ước tính hao mòn chủ quan, đòi hỏi am hiểu kỹ thuật xây dựng.','CĐ4 mục 3.2.3–3.2.4');

/* ===== THU NHẬP ===== */
q(2,'thunhap','Công thức vốn hóa trực tiếp là:',['V = I × R','V = I / R (I: thu nhập thuần; R: tỷ suất vốn hóa)','V = R / I','V = CF / (1+r)'],1,'Điều 5 Chuẩn mực cách tiếp cận từ thu nhập. Ví dụ I = 600 triệu/năm, R = 12% thì V = 5.000 triệu. Công thức ngầm định dòng thu nhập ổn định, vĩnh viễn.','Chuẩn mực cách tiếp cận từ thu nhập Điều 5');
q(2,'thunhap','Thu nhập thuần (I) theo Chuẩn mực được xác định như thế nào?',['Tổng thu nhập tiềm năng + thất thu − chi phí','Tổng thu nhập tiềm năng hoạt động − thất thu do không sử dụng hết 100% công suất và rủi ro thanh toán − chi phí hoạt động','Doanh thu − khấu hao','Giá bán − chi phí xây dựng'],1,'Điều 6: thất thu = tỷ lệ thất thu × tổng thu nhập tiềm năng, ước tính từ ít nhất 03 tài sản tương tự. Thu nhập và chi phí tính trước hay sau thuế phải nhất quán với cách xác định tỷ suất vốn hóa.','Chuẩn mực thu nhập Điều 6');
q(2,'thunhap','Có hai cách xác định tỷ suất vốn hóa R theo Chuẩn mực. Đó là:',['Phương pháp so sánh; phương pháp phân tích vốn vay – vốn sở hữu','CAPM; WACC','Thống kê; hồi quy','Chi phí; thặng dư'],0,'Điều 7. Phương pháp so sánh cần ít nhất 03 tài sản so sánh. Phương pháp vốn vay – vốn sở hữu: R = M × Rm + (1 − M) × Re. CAPM, WACC, thống kê là cách xác định tỷ suất CHIẾT KHẤU r (Điều 12) trong phương pháp dòng tiền chiết khấu.','Chuẩn mực thu nhập Điều 7, 12');
q(2,'thunhap','Tỷ lệ vay M = 70%, hệ số vốn hóa tiền vay Rm = 11%, tỷ suất vốn hóa vốn sở hữu Re = 9%. Tỷ suất vốn hóa R là:',['9,6%','10,0%','10,4%','11,0%'],2,'R = M × Rm + (1 − M) × Re = 0,7 × 11% + 0,3 × 9% = 7,7% + 2,7% = 10,4%.','Chuẩn mực thu nhập Điều 7');
q(2,'thunhap','Hệ số vốn hóa tiền vay (Rm) được tính như thế nào?',['Lãi suất danh nghĩa của khoản vay','Khoản thanh toán mỗi kỳ (gốc + lãi) × số kỳ thanh toán trong năm ÷ tổng số tiền vay gốc','Tổng lãi vay ÷ số năm','Gốc vay ÷ giá bán'],1,'Rm là tỷ lệ khoản thanh toán nợ hàng năm (cả vốn và lãi) trên vốn vay gốc. Tỷ suất vốn hóa vốn sở hữu Re = lợi nhuận vốn chủ sở hữu hàng năm ÷ tổng vốn sở hữu.','Chuẩn mực thu nhập Điều 7');
q(2,'thunhap','Một tài sản có dòng tiền đều A trong n năm, tỷ suất chiết khấu r, nhận cuối năm. Giá trị hiện tại là:',['A × n / r','A × [1 − (1+r)^(−n)] / r','A × (1+r)^n','A / (r × n)'],1,'Công thức niên kim hiện tại. Ví dụ A = 100, r = 10%, n = 5: V = 100 × (1 − 1,1^−5)/0,1 = 379,08. Khi n → ∞ thì V = A / r (vốn hóa trực tiếp).','CĐ4 mục 3.3.2 bước 5');
q(2,'thunhap','Dòng tiền hai giai đoạn: sau năm n dòng tiền tăng đều g%/năm vĩnh viễn. Điều kiện của mô hình và giá trị cuối kỳ Vn là:',['g > r; Vn = CFn × (1+g)/(r−g)','g < r; Vn = CFn+1/(r − g) = CFn × (1+g)/(r − g)','g = 0; Vn = CFn × r','Không có điều kiện'],1,'Điều 8 Chuẩn mực: g < r. Giá trị cuối kỳ Vn = CF(n+1)/(r − g). Hiện giá toàn phần = tổng hiện giá các CF từ năm 1 đến n + Vn/(1+r)^n. Ví dụ CF1 = 100, r = 12%, g = 4%: V = 100/0,08 = 1.250 (nếu tăng trưởng đều ngay từ năm 1).','Chuẩn mực thu nhập Điều 8, 11');
q(2,'thunhap','Giai đoạn dự báo dòng tiền cần căn cứ vào những yếu tố nào?',['Chỉ tuổi đời kinh tế','Tuổi đời kinh tế; giai đoạn dự định nắm giữ; độ tin cậy của thông tin; đủ dài để tài sản đạt thu nhập tương đối ổn định và tính được giá trị cuối kỳ','Chỉ giai đoạn vay vốn','Chỉ yêu cầu của khách hàng'],1,'Điều 9 Chuẩn mực.','Chuẩn mực thu nhập Điều 9');
q(2,'thunhap','Tỷ suất chiết khấu r được xác định bằng các cách nào theo Điều 12 Chuẩn mực?',['Thống kê tỷ suất sinh lời trung bình của tài sản tương tự; chi phí sử dụng vốn bình quân gia quyền (WACC); mô hình định giá tài sản vốn (CAPM)','Chỉ lãi suất ngân hàng','Chỉ cổ tức','Chỉ lạm phát'],0,'Tỷ suất chiết khấu phải phản ánh giá trị thời gian của tiền, rủi ro dòng tiền và việc sử dụng tài sản; phải nhất quán với dòng tiền (trước hay sau thuế).','Chuẩn mực thu nhập Điều 12');
q(2,'thunhap','Tính chung cư: tổng thu nhập thực tế 1.071 triệu, chi phí 35% thu nhập thực tế, thuế 25% lợi nhuận trước thuế, R = 20% (thu nhập sau thuế). Giá trị chung cư xấp xỉ:',['2.610 triệu','3.480 triệu','1.800 triệu','5.220 triệu'],0,'Chi phí = 0,35 × 1.071 = 374,85; LN trước thuế = 696,15; sau thuế = 522,11; V = 522,11/0,2 = 2.610 triệu. Nhất quán: thu nhập sau thuế phải đi với R sau thuế.','BÀI TẬP VẬN DỤNG BĐS, thu nhập bài 1');

/* ===== THẶNG DƯ ===== */
q(2,'thangdu','Phương pháp thặng dư áp dụng cho loại bất động sản nào và dựa trên nguyên tắc nào?',['Bất động sản đang cho thuê ổn định; nguyên tắc thay thế','Bất động sản có tiềm năng phát triển; nguyên tắc sử dụng tốt nhất và hiệu quả nhất, nguyên tắc đóng góp và dự kiến dòng lợi ích tương lai','Mọi bất động sản','Máy móc thiết bị'],1,'Giá trị BĐS = giá trị của sự phát triển (doanh thu) − tất cả chi phí để tạo ra sự phát triển (gồm lợi nhuận nhà đầu tư). Đó là giá trị còn lại, "thặng dư" dành cho đất.','CĐ4 mục 3.4.1');
q(2,'thangdu','Năm bước của phương pháp thặng dư theo thứ tự đúng là:',['Chi phí → doanh thu → sử dụng tốt nhất → giá trị → giai đoạn','Xác định sử dụng tốt nhất và hiệu quả nhất → xác định giai đoạn dự báo dòng tiền → tổng doanh thu phát triển → tổng chi phí phát triển → giá trị bất động sản','Doanh thu → chi phí → lợi nhuận → thuế → giá trị','Giá trị → doanh thu → chi phí → lợi nhuận → thuế'],1,'Doanh thu phát triển và chi phí phát triển được xác định từ thông tin tối thiểu 03 BĐS tương tự, theo cách tiếp cận thị trường hoặc thu nhập. Việc xác định "sử dụng tốt nhất" căn cứ quy hoạch, quy định chuyển mục đích và đầu tư xây dựng.','CĐ4 mục 3.4.1.2');
q(2,'thangdu','Tổng chi phí phát triển trong phương pháp thặng dư KHÔNG gồm khoản nào sau đây?',['Chi phí đầu tư xây dựng, thiết bị, tư vấn, quản lý dự án','Chi phí dự phòng; chi phí kinh doanh (quảng cáo, bán hàng)','Lợi nhuận của nhà đầu tư; chi phí tài chính; thuế','Giá trị quyền sử dụng đất cần thẩm định (chính là ẩn số của bài toán)'],3,'Giá đất là phần THẶNG DƯ cần tìm, không được đưa vào chi phí phát triển. Nếu bài cho giá đất trả bằng vốn vay thì phải gọi giá đất là ẩn số X và giải phương trình, vì lãi vay và lợi nhuận mua đất phụ thuộc X.','CĐ4 Bước 4; BÀI TẬP thặng dư bài 1');
q(2,'thangdu','Dự án bán hết trong một năm, doanh thu 180.000 triệu, tổng chi phí phát triển (gồm lợi nhuận) 13.500 triệu. Giá trị mảnh đất theo phương pháp thặng dư là:',['166.500 triệu','180.000 triệu','193.500 triệu','13.500 triệu'],0,'V = DT − CP = 180.000 − 13.500 = 166.500 triệu (khi doanh thu và chi phí cùng phát sinh trong cùng một năm, tính theo mặt bằng giá tại thời điểm thẩm định giá, không cần chiết khấu).','CĐ4 Bước 5 trường hợp 1; Thặng dư bài 2');
q(2,'thangdu','Doanh thu 1.210 triệu thu cuối năm 2; chi phí 600 triệu chi cuối năm 1; tỷ suất chiết khấu 10%. Giá trị thặng dư tại thời điểm thẩm định là:',['610 triệu','454,55 triệu','500 triệu','1.000 triệu'],1,'V = 1.210/1,1² − 600/1,1 = 1.000 − 545,45 = 454,55 triệu. Chi phí phát sinh năm nào phải chiết khấu đúng số năm đó. Một lỗi thường gặp: chiết khấu chi phí năm 2 như chi phí năm 1.','CĐ4 Bước 5 trường hợp 2');
q(2,'thangdu','Tỷ suất chiết khấu trong phương pháp thặng dư cần phản ánh:',['Chỉ lạm phát','Giá trị biến đổi theo thời gian của tiền và rủi ro liên quan đến dòng tiền trong quá trình xây dựng, hoàn thành và vận hành dự án','Chỉ lãi vay','Chỉ lợi nhuận mong muốn'],1,'Có thể xác định theo Chuẩn mực cách tiếp cận từ thu nhập hoặc dựa trên lãi suất cho vay trung bình và các căn cứ khác như chuyên đề hướng dẫn.','CĐ4 xác định tỷ suất chiết khấu');

/* ===== VẬN DỤNG TỔNG HỢP ===== */
q(2,'vandung','Tài sản có tỷ suất sinh lợi 10%. Nhà đầu tư dùng 50% vốn vay, lãi vay 8%/năm. Tỷ suất sinh lợi trên vốn chủ sở hữu là:',['9%','10%','12%','18%'],2,'ROE = [10% − 50% × 8%] / 50% = 6%/50% = 12%. Vay có lợi vì lãi vay (8%) thấp hơn tỷ suất sinh lợi của tài sản (10%) nên đòn bẩy tài chính làm tăng sinh lợi trên vốn chủ.','Đề thi 2017 câu 2d, 2e');
q(2,'vandung','Điều kiện để vay vốn đầu tư bất động sản có lợi cho nhà đầu tư (tăng tỷ suất sinh lợi trên vốn chủ sở hữu) là:',['Lãi suất vay lớn hơn tỷ suất sinh lợi của bất động sản','Lãi suất vay nhỏ hơn tỷ suất sinh lợi của bất động sản','Tỷ lệ vay phải bằng 100%','Lãi suất vay bằng 0'],1,'ROE = [y − M × i]/(1 − M) > y ⇔ i < y (với 0 < M < 1). Nên "lãi vay tối đa" để vay vẫn có lợi chính là tỷ suất sinh lợi của BĐS (đề 2017 câu 2e).','Đề thi 2017 câu 2e');
q(2,'vandung','Lãi suất danh nghĩa 12%/năm ghép lãi hàng quý. Lãi suất thực (hiệu dụng) hằng năm là:',['12,00%','12,36%','12,55%','12,68%'],2,'(1 + 12%/4)^4 − 1 = 1,03^4 − 1 = 12,55%. Ngân hàng nào ghép lãi nhiều lần hơn trong năm thì lãi suất thực cao hơn so với cùng lãi danh nghĩa; phải so sánh lãi thực để chọn nguồn vay.','Toán ứng dụng, CĐ2');
q(2,'vandung','Người thẩm định thu thập giá bán tài sản so sánh có thanh toán chậm; yếu tố nào được điều chỉnh đầu tiên khi lập bảng điều chỉnh?',['Hướng nhà','Điều kiện thanh toán/chi phí pháp lý (điều chỉnh số tiền tuyệt đối) cùng thời điểm giao dịch','Cảnh quan','Hạ tầng'],1,'Điều chỉnh về thời gian (nếu giá biến động) và điều kiện giao dịch, pháp lý đi trước, sau đó mới tới các yếu tố vật chất theo tỷ lệ %.','CĐ4; TT 32/2024');
q(2,'vandung','Điều chỉnh pháp lý: lô đất so sánh chưa có sổ nhưng đủ điều kiện được cấp nếu nộp tiền sử dụng đất 30 triệu đồng/m². Lô đất thẩm định đã có sổ. Điều chỉnh với lô so sánh là:',['−30 triệu đồng/m²','+30 triệu đồng/m²','+30%','Không điều chỉnh'],1,'Lô thẩm định có lợi thế "đã có sổ" mà lô so sánh chưa có, nên cộng thêm chi phí hợp thức hóa vào giá lô so sánh để quy về cùng trạng thái pháp lý.','BÀI TẬP VẬN DỤNG BĐS, so sánh bài 2');

/* ================= MÔN 3: ĐỘNG SẢN, MÁY THIẾT BỊ, TÀI SẢN VÔ HÌNH ================= */
/* ===== MÁY THIẾT BỊ: CÁCH TIẾP CẬN & HAO MÒN ===== */
q(3,'may_cp','Giá trị ước tính của máy, thiết bị theo phương pháp chi phí tái tạo là:',['Chi phí tái tạo (đã gồm lợi nhuận nhà sản xuất/nhà đầu tư) − tổng giá trị hao mòn','Chi phí thay thế + hao mòn','Giá nhập khẩu CIF','Giá bán lại × tuổi đời'],0,'Phương pháp chi phí thay thế dùng chi phí thay thế trừ hao mòn (không gồm phần hao mòn chức năng đã phản ánh trong chi phí thay thế). Phương pháp tổng cộng cộng giá trị các bộ phận cấu thành.','CĐ5 mục 5.2.5.2');
q(3,'may_cp','Máy, thiết bị thay thế là:',['Máy cùng model, cùng năm sản xuất','Máy có chức năng tương tự và tính hữu dụng tương đương với máy thẩm định, được chế tạo bằng công nghệ, vật liệu, kỹ thuật mới hơn','Máy cũ cùng loại','Máy nhập khẩu'],1,'Thay thế (replacement) khác tái tạo (reproduction: giống hệt). Chi phí thay thế đã loại phần lỗi thời công nghệ nên không phải trừ hao mòn chức năng lần nữa.','CĐ5');
q(3,'may_cp','Lợi nhuận của nhà sản xuất/nhà đầu tư trong chi phí tái tạo, thay thế được xác định theo Chuẩn mực như thế nào?',['Tỷ lệ cố định 10%','Tỷ lệ bình quân của lợi nhuận trước thuế TNDN trên tổng (giá vốn hàng bán + chi phí bán hàng + chi phí quản lý doanh nghiệp + chi phí tài chính) trong tối thiểu 03 năm gần nhất của ít nhất 03 doanh nghiệp, số liệu từ báo cáo tài chính đã kiểm toán; nhân với chi phí chưa gồm lợi nhuận','Do khách hàng quy định','Bằng lãi suất ngân hàng'],1,'Điều 9 Chuẩn mực cách tiếp cận từ chi phí. Nếu không xác định được theo cách trên thì dùng định mức do cơ quan nhà nước có thẩm quyền ban hành (nếu có).','TT 32/2024 Điều 9');
q(3,'may_hm','Tuổi đời hiệu quả của máy, thiết bị là:',['Số năm kể từ khi chế tạo xong','Số năm thể hiện thực trạng của máy tại thời điểm thẩm định giá, phụ thuộc duy trì, bảo dưỡng; có thể bằng, lớn hơn hoặc nhỏ hơn tuổi đời thực tế','Thời gian khấu hao theo thuế','Thời gian bảo hành'],1,'Ví dụ xe ben dùng 3 năm nhưng hoạt động quá công suất nên tuổi đời hiệu quả 5 năm. Cần cẩu bảo dưỡng đúng quy trình: tuổi đời hiệu quả = tuổi đời thực tế. Tuổi đời kinh tế: thời gian sử dụng còn phát huy hiệu quả kinh tế.','CĐ5; Bài tập chi phí bài 1, 3');
q(3,'may_hm','Cần cẩu có tuổi đời kinh tế 20 năm, tuổi đời hiệu quả 12 năm. Tỷ lệ hao mòn theo kỹ thuật tuổi đời là:',['12%','40%','60%','167%'],2,'12/20 × 100% = 60%.','Bài tập chi phí bài 3');
q(3,'may_hm','Ô tô bán tải: hao mòn các bộ phận lần lượt động cơ 20%, khung gầm 15%, hệ thống điện 5%, hệ thống khác 5%; tỷ trọng giá trị tương ứng 55%, 15%, 20%, 10% (tổng 100%). Tỷ lệ hao mòn vật lý của xe là:',['14,75%','11,25%','45%','100%'],0,'H = Σ (hao mòn bộ phận × tỷ trọng) / Σ tỷ trọng = (20%×55% + 15%×15% + 5%×20% + 5%×10%)/100% = (11 + 2,25 + 1 + 0,5)% = 14,75%. Bẫy: nếu tổng tỷ trọng khác 100% phải chia cho tổng tỷ trọng.','Bài tập chi phí bài 2; công thức hao mòn kết cấu chính');
q(3,'may_hm','Kỹ thuật "so sánh" xác định giá trị hao mòn đòi hỏi tối thiểu:',['01 tài sản tương tự trong 3 năm','Ít nhất 02 tài sản tương tự đã giao dịch thành công hoặc được chào mua/chào bán trong thời gian không quá 01 năm tính đến thời điểm thẩm định giá','Ít nhất 03 tài sản trong 24 tháng','Không giới hạn'],1,'Điều 10 Chuẩn mực cách tiếp cận từ chi phí. Các bước: điều chỉnh giá giao dịch → xác định chi phí tạo tài sản mới → hao mòn = chi phí mới − giá (đã loại giá đất) → tỷ lệ hao mòn → áp vào chi phí thay thế/tái tạo của tài sản thẩm định.','TT 32/2024 Điều 10');
q(3,'may_hm','Xe so sánh 1: giá bán 870 triệu, chi phí thay thế mới 1.500 triệu, tuổi đời hiệu quả 4 năm. Tỷ lệ hao mòn lũy kế và tỷ lệ hao mòn hàng năm là:',['42% và 10,5%','58% và 9,67%','42% và 4%','58% và 14,5%'],0,'Hao mòn lũy kế = 1.500 − 870 = 630 → 630/1.500 = 42%; hàng năm = 42%/4 = 10,5%. (Xe so sánh 2: 58%, 9,67%.) Từ đó hao mòn của xe cần thẩm định: tỷ lệ năm bình quân × tuổi đời hiệu quả 5 năm ≈ 50,4%.','Bài tập chi phí bài 1');
q(3,'may_hm','Dây chuyền có thu nhập thuần giảm từ 1.000 xuống 700 triệu/năm do thay đổi chính sách thuế, tuổi đời kinh tế còn lại 12 năm, tỷ suất 15%. Hao mòn kinh tế được tính:',['300 × 12','Hiện giá niên kim của 300 triệu trong 12 năm ở 15% ≈ 1.626,19 triệu','1.000 × 12 × 15%','700/15%'],1,'Hao mòn ngoại biên (kinh tế) = hiện tại hóa phần thu nhập bị mất hàng năm trong tuổi đời kinh tế còn lại: 300 × (1 − 1,15^−12)/0,15 = 300 × 5,4206 = 1.626,19.','Bài tập chi phí bài 4');

/* ===== KHẤU HAO ===== */
q(3,'may_hm','Doanh nghiệp khấu hao thiết bị theo phương pháp số dư giảm dần có điều chỉnh, thời gian trích khấu hao 4 năm. Hệ số điều chỉnh và tỷ lệ khấu hao nhanh năm đầu là:',['Hệ số 1,5; 37,5%','Hệ số 2; 50%','Hệ số 2,5; 62,5%','Hệ số 1; 25%'],0,'Quy định khấu hao: thời gian ≤ 4 năm hệ số 1,5; trên 4 đến 6 năm hệ số 2; trên 6 năm hệ số 2,5. Tỷ lệ nhanh = (1/4) × 1,5 = 37,5%. Đến những năm cuối, khi mức khấu hao theo số dư giảm dần thấp hơn mức bình quân giá trị còn lại/số năm còn lại thì chuyển sang khấu hao đường thẳng. (Quy định cụ thể có thể được sửa đổi; kiểm tra văn bản hiện hành.)','Bài tập thu nhập bài 2; TT 45/2013');

/* ===== MÁY THIẾT BỊ: THỊ TRƯỜNG & THU NHẬP ===== */
q(3,'may_tn','Tài sản so sánh được mua với thanh toán 40% ngay, 60% sau 1 năm, giá 120 triệu, lãi suất 12%/năm. Giá quy về thanh toán ngay là:',['120 triệu','112,29 triệu','108 triệu','117,6 triệu'],1,'48 + 72/1,12 = 48 + 64,29 = 112,29 triệu. Điều chỉnh về điều kiện thanh toán: chiết khấu phần trả chậm.','Bài tập thị trường bài 1');
q(3,'may_tn','Giá máy ủi sản xuất 2012 bằng 110% giá máy sản xuất 2010. Máy thẩm định sản xuất 2012, máy so sánh 1 sản xuất 2010. Tỷ lệ điều chỉnh cho máy so sánh 1 theo giáo trình là:',['−10%','+10%','+110%','0%'],1,'Máy so sánh kém hơn (2010 < 2012) nên điều chỉnh TĂNG: 110% − 100% = +10%. Các điều chỉnh khác của bài: công suất −10%, trọng lượng +5%, lực ủi −7%.','Bài tập thị trường bài 2');
q(3,'may_tn','Dây chuyền máy dự kiến dòng tiền thuần năm 1 là 700 triệu, mỗi năm sau tăng 10%, 5 năm, giá trị thu hồi cuối năm 5 là 50 triệu (trước thuế 20%), chi phí vốn 15%. Giá trị dây chuyền theo thu nhập khoảng:',['2.810 triệu','2.600 triệu','3.500 triệu','4.200 triệu'],0,'PV = Σ CFt/1,15^t + (50 × 0,8)/1,15^5 = 2.809,97 triệu. Giá thu hồi phải trừ thuế (50 × 80% = 40). Nếu giá chào là 2.800 thì IRR ≈ 15,14% (>15%) nên đáng mua.','Bài tập thu nhập bài 1');
q(3,'may_tn','WACC của phương án đầu tư: 70% vốn chủ (16%), 30% vốn vay (13%), thuế TNDN 20%. WACC là:',['14,5%','14,32%','15,1%','13,9%'],1,'WACC = 0,7×16% + 0,3×13%×(1−20%) = 11,2% + 3,12% = 14,32%. Chi phí vay phải tính sau thuế vì lãi vay được trừ khi tính thuế.','Bài tập thu nhập bài 2');
q(3,'may_tn','Quy tắc quyết định theo NPV và IRR cho một dự án đơn lẻ là:',['NPV < 0 và IRR > r thì chọn','NPV > 0 hoặc IRR > tỷ suất chiết khấu thì chấp nhận','Chọn dự án có IRR thấp nhất','NPV không liên quan đến quyết định'],1,'NPV > 0 ⇔ IRR > r (với dòng tiền thông thường). Khi chọn giữa các phương án loại trừ nhau thì ưu tiên NPV lớn hơn (ví dụ thiết bị X: NPV 27,61 triệu so với Y: 5,61 triệu).','Bài tập thu nhập bài 2, 3');

/* ===== TÀI SẢN VÔ HÌNH ===== */
q(3,'tsvh','Đặc điểm nào KHÔNG phải của tài sản vô hình theo Chuẩn mực?',['Không có hình thái vật chất','Nhận biết được và có bằng chứng hữu hình về sự tồn tại','Được pháp luật công nhận và bảo vệ, có thể được sở hữu tư nhân và chuyển giao','Giá trị không thể định lượng'],3,'Năm đặc điểm: không có hình thái vật chất; nhận biết được và có bằng chứng; pháp luật công nhận và bảo vệ; có khả năng tạo thu nhập; giá trị CÓ THỂ định lượng.','CĐ6 Tài sản vô hình');
q(3,'tsvh','Ba phương pháp thẩm định giá tài sản vô hình trong cách tiếp cận từ thu nhập là:',['Tiền sử dụng tài sản vô hình; lợi nhuận vượt trội; thu nhập tăng thêm','Chiết khấu dòng cổ tức; FCFE; FCFF','So sánh; chi phí thay thế; chi phí tái tạo','Vốn hóa trực tiếp; thặng dư; tổng cộng'],0,'Cách tiếp cận từ thu nhập đối với tài sản vô hình: tiền sử dụng (relief-from-royalty), lợi nhuận vượt trội (premium profits: chênh lệch hai dòng tiền có và không có tài sản), thu nhập tăng thêm (multi-period excess earnings). Phương án B dành cho thẩm định giá doanh nghiệp.','Chuẩn mực thu nhập Điều 4; CĐ6');
q(3,'tsvh','Phương pháp tiền sử dụng tài sản vô hình giả định gì?',['Chủ sở hữu bán tài sản ngay','Tổ chức không sở hữu tài sản vô hình phải trả tiền để sử dụng nó, nên giá trị là hiện giá của khoản tiền sử dụng tiết kiệm được (sau thuế) nhờ sở hữu tài sản','Doanh nghiệp được miễn thuế','Chi phí tạo ra tài sản bằng 0'],1,'Tiền sử dụng hoặc tỷ lệ tiền sử dụng xác định từ giao dịch tài sản tương tự trên thị trường hoặc từ việc chia tách lợi nhuận giữa bên cho phép và bên nhận chuyển nhượng. Dòng tiền, thuế, chi phí duy trì phải NHẤT QUÁN.','CĐ6 PP tiền sử dụng');
q(3,'tsvh','Thương hiệu tạo doanh thu 1.000 triệu/năm, tỷ lệ tiền sử dụng 5%, thuế TNDN 20%, thời gian 1 năm, chiết khấu 14%. Tiền sử dụng tiết kiệm sau thuế năm đó là:',['50 triệu','40 triệu','10 triệu','200 triệu'],1,'1.000 × 5% = 50; sau thuế 50 × (1 − 20%) = 40 triệu; hiện giá ở r = 14%: 40/1,14 ≈ 35,09. Với chuỗi 5 năm doanh thu 1.000→1.400 thì tổng hiện giá ≈ 161,22 triệu (xem bài tập trong mục Bài tính).','Ví dụ minh họa dựa trên CĐ6');
q(3,'tsvh','Phương pháp thu nhập tăng thêm xác định giá trị tài sản vô hình như thế nào?',['Hiện tại hóa dòng thu nhập phát sinh từ đóng góp của tài sản vô hình sau khi loại trừ phần đóng góp của các tài sản đóng góp khác (vốn lưu động, tài sản cố định hữu hình, các tài sản khác)','Lấy tổng doanh thu chia cho tuổi đời','Lấy chi phí xây dựng thương hiệu','So sánh với thương hiệu cùng ngành'],0,'Các bước: doanh thu kỳ vọng; thu nhập ròng; xác định thu nhập hợp lý của các tài sản đóng góp (giá trị thị trường × tỷ suất sinh lời hợp lý); loại trừ để còn dòng tiền riêng của tài sản vô hình (cộng lại khấu hao của tài sản đóng góp là tài sản cố định, trừ tiền mua sắm TSCĐ mới); chiết khấu về hiện tại.','CĐ6 PP thu nhập tăng thêm');
q(3,'tsvh','Trong cách tiếp cận từ chi phí đối với tài sản vô hình, khi xác định hao mòn cần cân nhắc:',['Chỉ hao mòn vật lý','Chênh lệch chi phí nghiên cứu, triển khai; chênh lệch chi phí vận hành; lỗi thời kinh tế; tuổi đời kinh tế và tuổi đời hiệu quả','Chỉ thuế','Chỉ lợi nhuận kế toán'],1,'Tài sản vô hình không có hao mòn vật lý như máy móc, nên tập trung vào lỗi thời chức năng/công nghệ và kinh tế.','CĐ6 cách tiếp cận chi phí');


/* ================= BỘ CÂU HỎI MỞ RỘNG (v2): tình huống, tính toán nhanh, phân biệt khái niệm ================= */
/* ===== Luật Giá (mở rộng) ===== */
q(1,'luatgia','Thẩm định giá của Nhà nước (Điều 59) do chủ thể nào thực hiện?',['Doanh nghiệp thẩm định giá theo hợp đồng dân sự','Hội đồng thẩm định giá theo quyết định của người có thẩm quyền','Hội Thẩm định giá Việt Nam','Cơ quan thuế'],1,'Điều 40 phân hai loại: dịch vụ thẩm định giá (doanh nghiệp, hợp đồng dân sự) và thẩm định giá của Nhà nước (hội đồng thẩm định giá, theo quyết định của người có thẩm quyền).','Luật Giá Đ.40, 59');
q(1,'luatgia','Mặt hàng nào sau đây KHÔNG nằm trong danh mục bình ổn giá (Phụ lục 1 Luật Giá)?',['Xăng dầu thành phẩm','Gạo tẻ','Thuốc thiết yếu tại cơ sở khám chữa bệnh','Điện thoại di động'],3,'Danh mục bình ổn giá gồm xăng dầu, LPG, sữa trẻ em dưới 06 tuổi, thóc gạo tẻ, phân bón (đạm, DAP, NPK), thức ăn chăn nuôi, thủy sản, vắc-xin gia súc gia cầm, thuốc bảo vệ thực vật, thuốc thiết yếu. Điện thoại không thuộc danh mục.','Luật Giá Phụ lục 1');
q(1,'luatgia','Nghị định nào hướng dẫn riêng về thẩm định giá theo Luật Giá 2023?',['Nghị định 85/2024/NĐ-CP','Nghị định 78/2024/NĐ-CP','Thông tư 45/2013/TT-BTC','Nghị định 30/2024/NĐ-CP'],1,'Nghị định 85/2024/NĐ-CP quy định chi tiết nhiều điều của Luật Giá; Nghị định 78/2024/NĐ-CP hướng dẫn về thẩm định giá. Thông tư 45/2013 là văn bản về chế độ trích khấu hao tài sản cố định.','CĐ1A; Luật Giá 2023');

/* ===== Thẻ & thẩm định viên (mở rộng) ===== */
q(1,'tdv','Anh A được cấp thẻ thẩm định viên cách đây 8 tháng và đủ các điều kiện khác. Khi đăng ký hành nghề, điều kiện nào anh A được miễn?',['Hợp đồng lao động với doanh nghiệp thẩm định giá','Thời gian làm việc thực tế tối thiểu','Đã cập nhật kiến thức về thẩm định giá','Năng lực hành vi dân sự đầy đủ'],2,'Điều 45 khoản 1 điểm d: điều kiện cập nhật kiến thức được miễn với thẻ cấp dưới 01 năm tính đến thời điểm đăng ký hành nghề. Các điều kiện còn lại vẫn bắt buộc.','Luật Giá Đ.45 k1d');
q(1,'tdv','Chị B là công chức nhà nước và đang có thẻ thẩm định viên. Chị B có được đăng ký hành nghề thẩm định giá không?',['Có, vì đã có thẻ','Có, nếu cơ quan đồng ý bằng văn bản','Không, cán bộ, công chức thuộc diện không được hành nghề thẩm định giá','Chỉ được hành nghề lĩnh vực tài sản'],2,'Điều 45 khoản 2 liệt kê cán bộ, công chức; lực lượng quân đội, công an theo quy định; người bị cấm hành nghề, đang bị khởi tố, truy tố, xét xử, người đang bị tước thẻ... là đối tượng không được hành nghề.','Luật Giá Đ.45 k2');
q(1,'tdv','Người tốt nghiệp đại học chuyên ngành giá hoặc thẩm định giá theo chương trình định hướng ứng dụng cần thời gian làm việc tối thiểu bao nhiêu để đăng ký hành nghề?',['12 tháng','24 tháng','36 tháng','60 tháng'],1,'Điều 45 khoản 1 điểm c: mức chung là 36 tháng; riêng trường hợp đại học trở lên chuyên ngành giá hoặc thẩm định giá theo chương trình định hướng ứng dụng thì rút còn 24 tháng.','Luật Giá Đ.45 k1c');

/* ===== Doanh nghiệp thẩm định giá (mở rộng) ===== */
q(1,'dntdg','Công ty cổ phần thẩm định giá có vốn điều lệ 100 tỷ đồng. Tổng vốn góp của các cổ đông là TỔ CHỨC tối đa là bao nhiêu?',['25 tỷ đồng','35 tỷ đồng','49 tỷ đồng','50 tỷ đồng'],1,'Điều 49: tổng phần vốn góp của thành viên/cổ đông là tổ chức không vượt quá 35% vốn điều lệ, tức 35 tỷ đồng. Đồng thời vốn của các thành viên/cổ đông là thẩm định viên phải chiếm trên 50%.','Luật Giá Đ.49');
q(1,'dntdg','Trong công ty thẩm định giá TNHH hai thành viên trở lên hoặc công ty cổ phần, phần vốn góp của các thành viên/cổ đông là thẩm định viên phải:',['Chiếm đúng 50% vốn điều lệ','Chiếm trên 50% vốn điều lệ','Chiếm ít nhất 35% vốn điều lệ','Không có yêu cầu'],1,'Điều 49: vốn góp của thành viên/cổ đông là thẩm định viên đăng ký hành nghề tại doanh nghiệp phải chiếm trên 50% vốn điều lệ. Con số 35% là mức trần dành cho thành viên là tổ chức.','Luật Giá Đ.49');
q(1,'dntdg','Một người từng là đại diện theo pháp luật của doanh nghiệp bị thu hồi giấy chứng nhận LẦN THỨ HAI thì bị hạn chế giữ chức vụ tương tự ở doanh nghiệp thẩm định giá trong bao lâu?',['12 tháng','24 tháng','36 tháng','60 tháng'],3,'Điều 51: thu hồi lần 1 thì hạn chế 12 tháng, thu hồi lần 2 thì hạn chế 60 tháng kể từ ngày bị thu hồi.','Luật Giá Đ.51');

/* ===== Hội đồng thẩm định giá (mở rộng) ===== */
q(1,'hdtdg','Hội đồng thẩm định giá có 6 thành viên. Phiên họp hợp lệ cần tối thiểu bao nhiêu thành viên có mặt?',['3','4','5','6'],1,'Điều 60: phải có ít nhất 2/3 số thành viên; 2/3 của 6 là 4. Riêng hội đồng chỉ có 03 thành viên thì phải có mặt đủ cả 03.','Luật Giá Đ.60 k3a');
q(1,'hdtdg','Hội đồng thẩm định giá có 7 thành viên. Tối thiểu bao nhiêu thành viên (gồm cả Chủ tịch) phải có chứng nhận chuyên môn theo Điều 60?',['2','3','4','5'],2,'Điều 60 khoản 2 yêu cầu ít nhất 50% thành viên, gồm cả Chủ tịch. 50% của 7 là 3,5 nên phải làm tròn lên thành 4 người.','Luật Giá Đ.60 k2');
q(1,'hdtdg','Thành viên hội đồng thẩm định giá không đồng ý với quyết định của hội đồng có quyền gì?',['Từ chối ký mọi văn bản về sau','Bảo lưu ý kiến của mình','Yêu cầu họp lại vô hạn','Tự phát hành kết luận riêng'],1,'Điều 60 khoản 3: hội đồng quyết định theo đa số; thành viên không đồng ý được bảo lưu ý kiến. Khi số phiếu ngang nhau thì ý kiến bên có biểu quyết của Chủ tịch là quyết định.','Luật Giá Đ.60 k3');

/* ===== Chứng thư, báo cáo (mở rộng) ===== */
q(1,'chungthu','Báo cáo thẩm định giá được ai phê duyệt?',['Khách hàng','Người đại diện theo pháp luật của doanh nghiệp thẩm định giá','Hội Thẩm định giá Việt Nam','Cơ quan thuế'],1,'Điều 55: thẩm định viên thực hiện thẩm định ký báo cáo, người đại diện theo pháp luật phê duyệt. Với chứng thư thì người đại diện (hoặc người đứng đầu chi nhánh) ký và đóng dấu.','Luật Giá Đ.55');
q(1,'chungthu','Chứng thư thẩm định giá phải được cập nhật vào hệ thống nào (trừ trường hợp bí mật nhà nước)?',['Cổng thông tin của khách hàng','Cơ sở dữ liệu quốc gia về giá','Sổ đăng ký của Tòa án','Hệ thống của Hội nghề nghiệp'],1,'Chứng thư thẩm định giá phải được cập nhật vào Cơ sở dữ liệu quốc gia về giá, trừ trường hợp thuộc bí mật nhà nước.','Luật Giá; Chuẩn mực về Hồ sơ TĐG');
q(1,'chungthu','Khách hàng muốn dùng một chứng thư thẩm định giá đã phát hành cách đây 8 tháng cho cùng tài sản, cùng mục đích. Nhận định nào đúng?',['Được, vì cùng tài sản và cùng mục đích','Được, nếu khách hàng cam kết giá không đổi','Không, vì chứng thư có hiệu lực tối đa 06 tháng','Không, vì chứng thư chỉ dùng được một lần'],2,'Chuẩn mực quy định chứng thư có hiệu lực kể từ ngày phát hành và tối đa không quá 06 tháng. Hết hiệu lực thì không còn giá trị sử dụng; cần thẩm định giá lại.','TT 30/2024 Đ.7; Luật Giá Đ.55 k4');

/* ===== Cơ sở giá trị (mở rộng) ===== */
q(1,'cosogt','Tài sản phải bán gấp trong thời gian rất ngắn nên không thể tiếp thị đầy đủ. Cơ sở giá trị phản ánh tình huống này là:',['Giá trị thị trường','Giá trị đầu tư','Giá trị bắt buộc phải bán','Giá trị thuê thị trường'],2,'Giá trị bắt buộc phải bán phản ánh giao dịch trong thời gian hạn chế, không tiếp thị đầy đủ, người mua có thể không kiểm tra đủ. Giá trị thị trường đòi hỏi tiếp thị đầy đủ và các bên không bị ép buộc.','Chuẩn mực Cơ sở giá trị Đ.8');
q(1,'cosogt','Cơ sở giá trị nào được dùng khi thẩm định giá để xác định mức tiền thuê của một quyền lợi bất động sản theo điều khoản thuê thích hợp?',['Giá trị thuê thị trường','Giá trị ngang bằng','Giá trị bắt buộc phải bán','Giá trị đầu tư'],0,'Giá trị thuê thị trường là khoản tiền ước tính để thuê một quyền lợi từ BĐS theo điều khoản thuê thích hợp, thường dùng khi thẩm định hợp đồng thuê.','Chuẩn mực Cơ sở giá trị');
q(1,'cosogt','Cơ sở giá trị nào được xác định theo pháp luật về lập báo cáo tài chính và chuẩn mực IFRS?',['Giá trị thị trường','Giá trị hợp lý','Giá trị đầu tư','Giá trị ngang bằng'],1,'Giá trị hợp lý là cơ sở giá trị theo pháp luật về lập báo cáo tài chính và IFRS. Chuẩn mực liệt kê cơ sở giá trị gồm nhưng không giới hạn: thị trường, thuê thị trường, đầu tư, bắt buộc phải bán, ngang bằng.','Chuẩn mực Cơ sở giá trị Đ.4');

/* ===== Thu thập & phân tích thông tin (mở rộng) ===== */
q(1,'thongtin','Phương án sử dụng tốt nhất và hiệu quả nhất của bất động sản cần thỏa mãn điều kiện nào?',['Chỉ cần mang lại lợi nhuận cao nhất','Phù hợp pháp luật, khả thi về vật chất, kỹ thuật và mang lại hiệu quả kinh tế cao nhất','Phù hợp ý muốn của chủ sở hữu','Giống hiện trạng đang sử dụng'],1,'Theo Chuẩn mực, đây là việc sử dụng tài sản phù hợp pháp luật, khả thi về vật chất và kỹ thuật, đồng thời mang lại hiệu quả kinh tế cao nhất. Không nhất thiết trùng hiện trạng.','TT 31/2024 Đ.8');
q(1,'thongtin','Thông tin tài sản so sánh thu thập trên Internet chỉ được chấp nhận khi từ nguồn nào?',['Mọi trang mạng xã hội','Website chính thức của cơ quan, tổ chức hoạt động theo quy định của pháp luật','Tin nhắn của người môi giới','Bất kỳ diễn đàn nào có nhiều người xem'],1,'Chuẩn mực yêu cầu thông tin từ website chính thức của cơ quan, tổ chức hoạt động hợp pháp; phiếu thu thập phải dẫn chiếu đường link và lưu hình ảnh minh chứng.','TT 32/2024 Đ.6');
q(1,'thongtin','Một tài sản so sánh có các điều chỉnh +5%, −8% và +3%. Tổng điều chỉnh THUẦN và GỘP lần lượt là:',['0% và 16%','0% và 0%','16% và 0%','−8% và 16%'],0,'Thuần có tính dấu: +5 − 8 + 3 = 0%. Gộp cộng giá trị tuyệt đối: 5 + 8 + 3 = 16%. Gộp lớn là dấu hiệu tài sản so sánh ít tương đồng dù thuần bằng 0.','TT 32/2024 Đ.3');

/* ===== Pháp luật doanh nghiệp (mở rộng) ===== */
q(1,'phapluatdn','Loại hình doanh nghiệp nào có vốn chia thành các phần bằng nhau gọi là cổ phần và được quyền phát hành cổ phần?',['Công ty TNHH một thành viên','Công ty TNHH hai thành viên trở lên','Công ty cổ phần','Công ty hợp danh'],2,'Công ty cổ phần có vốn chia thành cổ phần bằng nhau, cổ đông tối thiểu 03 và không hạn chế tối đa. Công ty TNHH không được phát hành cổ phần.','CĐ1A Pháp luật doanh nghiệp');
q(1,'phapluatdn','Người đại diện theo pháp luật của doanh nghiệp tư nhân là:',['Giám đốc thuê ngoài','Chủ doanh nghiệp tư nhân','Chủ tịch hội đồng quản trị','Thành viên hợp danh'],1,'Doanh nghiệp tư nhân do một cá nhân làm chủ; chủ doanh nghiệp là người đại diện theo pháp luật, chịu trách nhiệm vô hạn bằng toàn bộ tài sản.','CĐ1A Pháp luật doanh nghiệp');
q(1,'phapluatdn','Thành viên góp vốn trong công ty hợp danh chịu trách nhiệm như thế nào?',['Vô hạn bằng toàn bộ tài sản','Hữu hạn trong phạm vi số vốn đã góp','Không chịu trách nhiệm','Liên đới cùng thành viên hợp danh'],1,'Công ty hợp danh có hai nhóm: thành viên hợp danh (ít nhất 2 cá nhân, trách nhiệm vô hạn, có quyền đại diện) và thành viên góp vốn (trách nhiệm hữu hạn trong phạm vi vốn góp).','CĐ1A Pháp luật doanh nghiệp');

/* ===== Thuế (mở rộng) ===== */
q(1,'thue','Thanh tra thuế tại doanh nghiệp có thời hạn tối đa là bao nhiêu ngày (chưa tính gia hạn)?',['5 ngày','10 ngày','30 ngày','60 ngày'],2,'Theo tài liệu: thanh tra thuế tối đa 30 ngày, gia hạn không quá 30 ngày. Kiểm tra thuế tại trụ sở người nộp thuế ngắn hơn: không quá 5 ngày, gia hạn một lần không quá 5 ngày.','CĐ1A Pháp luật thuế');
q(1,'thue','Văn bản nào là cơ sở pháp lý chính về quản lý thuế hiện hành được nêu trong chuyên đề?',['Luật Quản lý thuế 2019','Luật Giá 2023','Luật Phá sản 2014','Bộ luật Dân sự 2015'],0,'Luật Quản lý thuế 2019 quy định cơ chế tự khai, tự nộp cùng quy trình kiểm tra, thanh tra thuế.','CĐ1A Pháp luật thuế');
q(1,'thue','Thỏa thuận trước về phương pháp xác định giá tính thuế (APA) nhằm mục đích chủ yếu nào?',['Tăng thuế suất cho doanh nghiệp','Hạn chế tình trạng chuyển giá, tránh thuế','Miễn thuế cho doanh nghiệp nước ngoài','Thay thế việc kê khai thuế'],1,'Chuyên đề nêu giải pháp chống chuyển giá và lợi dụng thiên đường thuế: quản lý giá, định mức chi phí và thỏa thuận trước về phương pháp xác định giá tính thuế (APA).','CĐ1A Pháp luật thuế');

/* ===== Hợp đồng (mở rộng) ===== */
q(1,'hopdong','Hợp đồng thẩm định giá giữa doanh nghiệp thẩm định giá và khách hàng có bản chất là:',['Hợp đồng hành chính','Hợp đồng dân sự','Quyết định hành chính','Văn bản thỏa thuận không ràng buộc'],1,'Điều 40 và 57 Luật Giá: dịch vụ thẩm định giá được thực hiện qua hợp đồng dân sự; giá dịch vụ do hai bên thỏa thuận. Khi tranh chấp áp dụng Điều 58 (thương lượng, hòa giải; trọng tài; Tòa án).','Luật Giá Đ.40, 57, 58');
q(1,'hopdong','Một hợp đồng được coi là vô hiệu khi nào?',['Khi một bên cho rằng hợp đồng bất lợi','Khi có tuyên bố của Tòa án hoặc trọng tài','Khi hợp đồng không có dấu của công ty','Khi hợp đồng quá 1 năm'],1,'Hợp đồng chỉ vô hiệu khi có tuyên bố của Tòa án (hoặc trọng tài); có thể vô hiệu toàn bộ, từng phần hoặc không vô hiệu.','CĐ1A Hợp đồng');
q(1,'hopdong','Khi hợp đồng bị tuyên vô hiệu, bên có lỗi gây ra vô hiệu phải làm gì thêm ngoài việc hoàn trả?',['Không phải làm gì thêm','Bồi thường thiệt hại','Chịu phạt tù','Nộp phí cho trọng tài'],1,'Hậu quả vô hiệu: các bên khôi phục tình trạng ban đầu, hoàn trả cho nhau những gì đã nhận; bên có lỗi phải bồi thường thiệt hại.','CĐ1A Hợp đồng');

/* ===== SHTT (mở rộng) ===== */
q(1,'shtt','Quyền đối với giống cây trồng được xác lập trên cơ sở nào?',['Tự động từ khi lai tạo','Bằng bảo hộ giống cây trồng','Hợp đồng chuyển nhượng','Đăng ký kinh doanh'],1,'Quyền đối với giống cây trồng xác lập theo Bằng bảo hộ giống cây trồng do cơ quan có thẩm quyền cấp; khác với quyền tác giả phát sinh tự động.','CĐ1A SHTT; Luật SHTT');
q(1,'shtt','Đối tượng nào sau đây thuộc quyền sở hữu công nghiệp?',['Tác phẩm văn học','Kiểu dáng công nghiệp','Bản ghi âm','Chương trình biểu diễn'],1,'Quyền sở hữu công nghiệp gồm sáng chế, kiểu dáng công nghiệp, thiết kế bố trí mạch tích hợp, nhãn hiệu, chỉ dẫn địa lý... Tác phẩm văn học thuộc quyền tác giả; bản ghi âm, biểu diễn thuộc quyền liên quan.','CĐ1A SHTT');
q(1,'shtt','Vì sao thẩm định giá tài sản vô hình cần kiến thức về pháp luật sở hữu trí tuệ?',['Vì tài sản vô hình phải được pháp luật công nhận và bảo vệ','Vì tài sản vô hình luôn có giá trị thấp','Vì chỉ cần giá thị trường','Vì không cần kiểm tra quyền sở hữu'],0,'Một trong các đặc điểm của tài sản vô hình là được pháp luật công nhận và bảo vệ, có thể sở hữu và chuyển giao. Không xác lập được quyền thì không có cơ sở định giá.','CĐ1A SHTT; Bài học Tài sản vô hình');

/* ===== Nguyên lý (mở rộng) ===== */
q(1,'nguyenly','Quyền sử dụng đất thuộc loại tài sản thẩm định giá nào trong bốn loại cơ bản?',['Động sản','Bất động sản','Doanh nghiệp','Tài sản vô hình'],1,'Bốn loại tài sản: bất động sản, động sản, doanh nghiệp, tài sản vô hình. Đất đai là một nhóm của bất động sản theo Điều 107 Bộ luật Dân sự 2015.','CĐ2; BLDS Đ.107');
q(1,'nguyenly','Chuẩn mực thẩm định giá có bao nhiêu chuẩn mực áp dụng cho tài sản cụ thể (không tính nhóm áp dụng chung)?',['1','3','5','8'],1,'Trong 11 chuẩn mực có 8 chuẩn mực áp dụng chung và 3 chuẩn mực áp dụng cho tài sản cụ thể: doanh nghiệp, tài sản vô hình, bất động sản.','CĐ2 mục 2.2.3');
q(1,'nguyenly','Vai trò nào sau đây của thẩm định giá được nêu trong chuyên đề?',['Quyết định giá bán cuối cùng thay chủ sở hữu','Góp phần minh bạch hóa thị trường, hỗ trợ Nhà nước quản lý tài sản, ngân sách','Thay thế hoàn toàn cơ quan thuế','Bảo đảm lợi nhuận cho khách hàng'],1,'Vai trò gồm minh bạch hóa thị trường, hỗ trợ Nhà nước quản lý tài sản và ngân sách, hỗ trợ người dân và doanh nghiệp giao dịch, đầu tư, thuận lợi hội nhập. Quyết định giá thuộc chủ sở hữu hoặc người có thẩm quyền.','CĐ2 mục 2.2.1');

/* ===== Tổng quan BĐS (mở rộng, Môn 2) ===== */
q(2,'bds_tq','Đặc điểm nào của bất động sản khiến việc chuyển thành tiền mặt thường mất nhiều thời gian?',['Thanh khoản kém','Tính khan hiếm','Tính cố định','Tính lâu bền'],0,'Thanh khoản kém là một trong tám đặc điểm của BĐS: giá trị lớn, thủ tục phức tạp nên giao dịch mất thời gian, không dễ chuyển nhanh thành tiền.','Bài học BĐS – BĐS');
q(2,'bds_tq','Thị trường bất động sản thuộc dạng thị trường nào?',['Cạnh tranh hoàn hảo','Không hoàn hảo, mang tính khu vực','Độc quyền hoàn toàn','Thị trường tập trung thống nhất toàn quốc'],1,'Thị trường BĐS là dạng điển hình của thị trường không hoàn hảo: mang tính khu vực, cung cầu ít co giãn, hàng hóa và địa điểm giao dịch tách biệt, chịu sự kiểm soát của Nhà nước.','Bài học BĐS – thị trường BĐS');
q(2,'bds_tq','Theo Điều 107 khoản 1 Bộ luật Dân sự 2015, bất động sản gồm mấy nhóm?',['3','4','5','6'],2,'Gồm 5 nhóm: đất đai; nhà, công trình xây dựng gắn liền với đất đai; tài sản gắn liền với đất đai, nhà, công trình xây dựng; các tài sản khác gắn liền với đất đai; tài sản khác theo quy định của pháp luật.','BLDS 2015 Đ.107 k1');
q(2,'bds_tq','Phương pháp thặng dư thích hợp nhất để thẩm định giá loại bất động sản nào?',['Căn hộ đã hoàn thiện, giao dịch nhiều','Bất động sản có tiềm năng phát triển','Công trình đã hết tuổi thọ','Tài sản vô hình gắn liền với đất'],1,'Thặng dư xác định giá trị BĐS có tiềm năng phát triển bằng giá trị phát triển giả định trừ mọi chi phí phát triển, gồm cả lợi nhuận nhà đầu tư.','Bài học BĐS – thặng dư');
q(2,'bds_tq','Theo trình tự phạm vi công việc thẩm định giá BĐS, bước đầu tiên là gì?',['Chọn phương pháp thẩm định giá','Lập báo cáo và chứng thư','Trao đổi với bên yêu cầu để xác định mục đích, cơ sở giá trị','Phát hành chứng thư'],2,'Trình tự: trao đổi với bên yêu cầu, lập kế hoạch, thu thập và phân tích thông tin, chọn và áp dụng phương pháp, xác định giá trị, lập báo cáo và chứng thư.','Bài học BĐS – thẩm định giá BĐS');

/* ===== Phương pháp so sánh (mở rộng) ===== */
q(2,'sosanh','Ba mức giá chỉ dẫn là 18; 22 và 23 triệu đồng/m² (trung bình 21). Mức lệch lớn nhất so với trung bình và kết luận theo nguyên tắc khống chế 15%?',['14,29%, thỏa nguyên tắc','14,29%, không thỏa nguyên tắc','16,67%, không thỏa nguyên tắc','9,52%, thỏa nguyên tắc'],0,'Trung bình = (18+22+23)/3 = 21. Lệch của 18: (21−18)/21 = 14,29%; của 22: 4,76%; của 23: 9,52%. Lệch lớn nhất 14,29% ≤ 15% nên thỏa. (16,67% là sai vì chia cho 18 thay vì chia cho trung bình.)','Bài học BĐS – phương pháp so sánh');
q(2,'sosanh','Tài sản so sánh có vị trí tốt hơn tài sản thẩm định 10% (quy đổi: so sánh = 110, thẩm định = 100). Tỷ lệ điều chỉnh áp dụng cho giá tài sản so sánh là:',['−10%','−9,09%','+10%','+9,09%'],1,'Tỷ lệ điều chỉnh = mục tiêu / so sánh − 1 = 100/110 − 1 = −9,09%. Lấy BĐS thẩm định làm chuẩn; yếu tố của tài sản so sánh tốt hơn thì điều chỉnh giảm.','Bài học BĐS – phương pháp so sánh');
q(2,'sosanh','Thứ tự điều chỉnh các yếu tố so sánh nào sau đây đúng?',['Kinh tế–kỹ thuật trước, pháp lý và điều kiện giao dịch sau','Pháp lý và điều kiện giao dịch (thời gian, thanh toán) trước; kinh tế–kỹ thuật sau, số tiền tuyệt đối trước, tỷ lệ phần trăm sau','Tất cả điều chỉnh đồng thời','Chỉ điều chỉnh yếu tố vị trí'],1,'Điều chỉnh nhóm pháp lý và điều kiện giao dịch trước (đưa giá về mặt bằng thời điểm, điều kiện thanh toán), sau đó điều chỉnh yếu tố kinh tế–kỹ thuật; trong đó số tiền tuyệt đối trước, tỷ lệ % sau.','Bài học BĐS – phương pháp so sánh');
q(2,'sosanh','Phương pháp chiết trừ: nhà 100 m² sàn, đơn giá xây mới 6 triệu đồng/m², chất lượng còn lại 80%. Giá bán cả bất động sản là 3.000 triệu đồng. Giá trị đất ước tính là:',['2.400 triệu đồng','2.520 triệu đồng','3.000 triệu đồng','3.480 triệu đồng'],1,'Giá trị còn lại công trình = 100 × 6 × 80% = 480 triệu. Giá trị đất = 3.000 − 480 = 2.520 triệu. (3.480 là cộng thay vì trừ; 2.400 là trừ cả giá xây mới 600 mà không tính hao mòn... 3.000 − 600.)','Bài học BĐS – phương pháp chiết trừ');

/* ===== Cách tiếp cận chi phí BĐS (mở rộng) ===== */
q(2,'chiphi','Chi phí tái tạo khác chi phí thay thế ở điểm nào?',['Tái tạo: công trình giống hệt, vật liệu và thiết kế như cũ, mới 100%; thay thế: công trình có công dụng tương tự nhưng vật liệu, công nghệ hiện đại hơn','Hai khái niệm giống hệt nhau','Tái tạo luôn thấp hơn thay thế','Thay thế chỉ áp dụng cho đất'],0,'Chi phí tái tạo là chi phí xây công trình giống hệt, mới 100%; chi phí thay thế là chi phí xây công trình có chức năng tương tự bằng vật liệu, công nghệ, thiết kế hiện đại. Với công trình mới, hai khái niệm này bằng nhau.','Bài học BĐS – cách tiếp cận chi phí');
q(2,'chiphi','Bước đầu tiên của cách tiếp cận chi phí trong thẩm định giá bất động sản là:',['Tính tổng hao mòn','Ước tính giá trị của lô đất như đất trống theo sử dụng tốt nhất và hiệu quả nhất','Tính chi phí xây lại công trình','Cộng giá đất với giá công trình'],1,'Năm bước: (1) giá đất như đất trống theo sử dụng tốt nhất và hiệu quả nhất; (2) chi phí xây lại công trình; (3) tổng hao mòn; (4) giá trị hiện tại của công trình = (2) − (3); (5) giá trị BĐS = (1) + (4).','Bài học BĐS – cách tiếp cận chi phí');
q(2,'chiphi','Giá đất 2.000 triệu đồng, chi phí xây lại công trình 1.500 triệu đồng, tổng hao mòn của công trình 20%. Giá trị bất động sản theo cách tiếp cận chi phí là:',['3.100 triệu đồng','3.200 triệu đồng','3.500 triệu đồng','2.800 triệu đồng'],1,'Công trình còn lại = 1.500 × (1 − 20%) = 1.200. Giá trị BĐS = 2.000 + 1.200 = 3.200 triệu. Hao mòn chỉ áp dụng cho công trình, không áp dụng cho đất.','Bài học BĐS – cách tiếp cận chi phí');
q(2,'chiphi','Hao mòn ngoại biên của bất động sản có thể ước tính bằng cách nào?',['Phân tích giá giao dịch các tài sản tương tự hoặc vốn hóa phần thu nhập bị mất','Chỉ dựa trên tuổi đời của công trình','Lấy bằng 0 trong mọi trường hợp','Chia chi phí xây dựng cho tuổi đời kinh tế'],0,'Hao mòn ngoại biên do nhân tố bên ngoài tài sản gây ra (thị trường, quy hoạch, môi trường); ước tính bằng phân tích giá giao dịch tương tự hoặc vốn hóa phần thu nhập bị mất.','Bài học BĐS – cách tiếp cận chi phí');

/* ===== Cách tiếp cận thu nhập (mở rộng) ===== */
q(2,'thunhap','Thu nhập thuần hằng năm của bất động sản là 1.200 triệu đồng, tỷ suất vốn hóa 8%. Giá trị ước tính theo vốn hóa trực tiếp là:',['96 triệu đồng','13.200 triệu đồng','15.000 triệu đồng','16.200 triệu đồng'],2,'V = I / R = 1.200 / 0,08 = 15.000 triệu đồng. (96 là phép nhân I × R, sai công thức.)','Bài học BĐS – vốn hóa trực tiếp');
q(2,'thunhap','Thu nhập thuần (I) trong vốn hóa trực tiếp được xác định như thế nào?',['Tổng thu nhập tiềm năng cộng thất thu trừ chi phí','Tổng thu nhập tiềm năng trừ thất thu (do không sử dụng hết công suất, rủi ro thanh toán) trừ chi phí hoạt động','Tổng doanh thu thực tế không trừ chi phí','Giá bán trừ giá mua'],1,'I = tổng thu nhập tiềm năng − thất thu − chi phí hoạt động. Tính trước hay sau thuế phải nhất quán với tỷ suất vốn hóa R.','Bài học BĐS – vốn hóa trực tiếp');
q(2,'thunhap','Tỷ lệ vay M = 60%, tỷ suất vốn hóa vốn vay Rm = 9%, tỷ suất vốn hóa vốn sở hữu Re = 12%. Tỷ suất vốn hóa chung R là:',['10,2%','10,8%','10,5%','21%'],0,'R = M × Rm + (1 − M) × Re = 0,6 × 9% + 0,4 × 12% = 5,4% + 4,8% = 10,2%. (10,8% là kết quả khi đổi chỗ trọng số.)','Bài học BĐS – vốn hóa trực tiếp');
q(2,'thunhap','Trong dòng tiền chiết khấu hai giai đoạn, giá trị cuối kỳ Vn = CF(n+1) / (r − g). Điều kiện nào phải thỏa mãn?',['g lớn hơn r','g nhỏ hơn r','g bằng 0','r bằng 0'],1,'Công thức tăng trưởng đều vô hạn chỉ có nghĩa khi tốc độ tăng trưởng g nhỏ hơn tỷ suất chiết khấu r. Nếu g ≥ r mẫu số bằng 0 hoặc âm, giá trị vô nghĩa.','Bài học BĐS – dòng tiền chiết khấu');

/* ===== Thặng dư (mở rộng) ===== */
q(2,'thangdu','Trong phương pháp thặng dư, lợi nhuận của nhà đầu tư phát triển được xử lý như thế nào?',['Không tính vì là thu nhập của chủ đất','Tính vào chi phí phát triển','Cộng vào doanh thu phát triển','Chia cho giá đất'],1,'Chi phí phát triển gồm chi phí đầu tư xây dựng, dự phòng, kinh doanh, tài chính, thuế, chi phí hợp lý khác và lợi nhuận nhà đầu tư. Giá trị đất = doanh thu − toàn bộ các chi phí này.','Bài học BĐS – phương pháp thặng dư');
q(2,'thangdu','Tổng doanh thu phát triển dự án là 500 tỷ đồng, tổng chi phí phát triển (đã gồm lợi nhuận nhà đầu tư) là 380 tỷ đồng, thu chi cùng mặt bằng giá. Giá trị khu đất là:',['120 tỷ đồng','380 tỷ đồng','500 tỷ đồng','880 tỷ đồng'],0,'V = DT − CP = 500 − 380 = 120 tỷ đồng khi thu và chi cùng một mặt bằng thời gian, không cần chiết khấu.','Bài học BĐS – phương pháp thặng dư');
q(2,'thangdu','Dự án kéo dài nhiều năm, khi chiết khấu dòng tiền trong phương pháp thặng dư cần lưu ý gì?',['Chiết khấu tất cả về một năm bất kỳ','Chiết khấu đúng số năm phát sinh của từng khoản thu, chi','Không chiết khấu chi phí','Chỉ chiết khấu doanh thu'],1,'V = Σ (DTt − CPt) / (1 + r)^t. Mỗi khoản phải được chiết khấu đúng số năm kể từ thời điểm thẩm định giá đến khi phát sinh.','Bài học BĐS – phương pháp thặng dư');

/* ===== Máy thiết bị: chi phí (mở rộng, Môn 3) ===== */
q(3,'may_cp','Chi phí thay thế của máy (đã gồm lợi nhuận nhà sản xuất) là 1.000 triệu đồng. Tổng hao mòn gồm vật lý 30% và ngoại biên 10% chi phí thay thế. Giá trị máy theo cách tiếp cận chi phí là:',['600 triệu đồng','700 triệu đồng','630 triệu đồng','400 triệu đồng'],0,'Tổng hao mòn = 30% + 10% = 40% của 1.000 = 400 triệu. Giá trị = chi phí thay thế − tổng hao mòn = 1.000 − 400 = 600 triệu.','Bài học Máy thiết bị – cách tiếp cận chi phí');
q(3,'may_cp','Để xác định tỷ lệ lợi nhuận nhà sản xuất khi thẩm định giá máy theo chi phí, số liệu cần thỏa mãn yêu cầu nào?',['Một doanh nghiệp, năm gần nhất, báo cáo nội bộ','Từ ít nhất 03 năm gần nhất, ít nhất 03 doanh nghiệp, báo cáo tài chính đã kiểm toán','Bất kỳ số liệu nào trên Internet','Chỉ cần số liệu của khách hàng'],1,'Tỷ lệ bình quân lợi nhuận trước thuế trên chi phí (giá vốn, bán hàng, quản lý, tài chính) trong ít nhất 03 năm gần nhất, ít nhất 03 doanh nghiệp, số liệu từ BCTC đã kiểm toán; không xác định được thì dùng định mức nhà nước (nếu có).','Bài học Máy thiết bị – cách tiếp cận chi phí');
q(3,'may_cp','Chi phí hình thành của máy móc nhập khẩu được tính chủ yếu bằng:',['Giá FOB nhân thuế suất','Giá CIF × tỷ giá + thuế nhập khẩu + chi phí vận chuyển, lắp đặt, chạy thử','Giá trong nước cộng 10%','Chi phí lương nhân công'],1,'Chi phí máy nhập khẩu = giá CIF × tỷ giá + thuế nhập khẩu và các thuế phí liên quan + chi phí vận chuyển, lắp đặt, chạy thử... Dùng cho máy mới hoặc được chế tạo, và để đối chiếu với các cách tiếp cận khác.','Bài học Máy thiết bị – cách tiếp cận chi phí');
q(3,'may_cp','Phương pháp tổng cộng trong cách tiếp cận chi phí thích hợp khi nào?',['Khi giá trị máy phụ thuộc chủ yếu vào giá trị các bộ phận cấu thành','Khi chỉ có một giao dịch so sánh','Khi máy đã hết tuổi thọ','Khi không cần tính hao mòn'],0,'Phương pháp tổng cộng cộng giá trị các bộ phận cấu thành tài sản; phù hợp khi giá trị của máy phụ thuộc chủ yếu vào giá trị các bộ phận.','Bài học Máy thiết bị – cách tiếp cận chi phí');
q(3,'may_cp','Khi áp dụng phương pháp chi phí thay thế, hao mòn chức năng nào không được trừ lần nữa?',['Hao mòn chức năng đã được phản ánh trong chi phí thay thế','Hao mòn vật lý','Hao mòn ngoại biên','Mọi hao mòn đều phải trừ'],0,'Chi phí thay thế đã dùng thiết kế, công nghệ hiện đại nên phản ánh sẵn phần lỗi thời về chức năng. Trừ thêm nữa sẽ tính trùng hao mòn.','Bài học Máy thiết bị – cách tiếp cận chi phí');

/* ===== Máy thiết bị: hao mòn (mở rộng) ===== */
q(3,'may_hm','Tuổi đời hiệu quả của máy là 6 năm, tuổi đời kinh tế là 15 năm. Tỷ lệ hao mòn theo kỹ thuật tuổi đời là:',['6%','25%','40%','60%'],2,'Tỷ lệ hao mòn = tuổi đời hiệu quả / tuổi đời kinh tế = 6/15 = 40%.','Bài học Máy thiết bị – hao mòn');
q(3,'may_hm','Bước cuối cùng khi ước tính hao mòn chức năng do chi phí vận hành cao là:',['Cộng thêm lợi nhuận nhà sản xuất','Hiện tại hóa tổng chênh lệch chi phí vận hành (sau giảm trừ thuế TNDN)','Nhân với tuổi đời thực tế','Lấy bằng chi phí khắc phục'],1,'Sáu bước kết thúc bằng việc quy về hiện tại tổng chênh lệch chi phí vận hành hằng năm (đã giảm trừ thuế thu nhập doanh nghiệp) trong thời gian sử dụng còn lại.','Bài học Máy thiết bị – hao mòn');
q(3,'may_hm','Hao mòn ngoại biên của máy móc thiết bị thường có đặc điểm nào?',['Luôn khắc phục được bằng sửa chữa','Do nhân tố bên ngoài (thị trường, thuế, quy định) và thường không khắc phục được','Chỉ phát sinh do sử dụng lâu','Bằng hao mòn vật lý'],1,'Hao mòn ngoại biên (kinh tế) do tác động bên ngoài tài sản, ví dụ cầu giảm, quy định mới, thuế; chủ sở hữu thường không thể khắc phục.','Bài học Máy thiết bị – hao mòn');
q(3,'may_hm','Theo phương pháp khấu hao số dư giảm dần có điều chỉnh, tài sản có thời gian trích khấu hao trên 4 đến 6 năm dùng hệ số điều chỉnh là:',['1,0','1,5','2,0','2,5'],2,'Hệ số: 1,5 với thời gian trích khấu hao tối đa 4 năm; 2,0 với trên 4 đến 6 năm; 2,5 với trên 6 năm. Cuối kỳ chuyển sang khấu hao đường thẳng.','Bài học Máy thiết bị – khấu hao');
q(3,'may_hm','Máy tương tự có chi phí mới 1.000 triệu đồng, vừa bán với giá 700 triệu đồng, tuổi đời hiệu quả 3 năm. Tỷ lệ hao mòn bình quân hằng năm (đường thẳng) theo kỹ thuật so sánh là:',['7%','10%','23,33%','30%'],1,'Hao mòn lũy kế = (1.000 − 700) / 1.000 = 30%; chia 3 năm = 10%/năm. Áp tỷ lệ này cho tuổi đời hiệu quả của máy thẩm định. (30% là hao mòn lũy kế, chưa chia năm.)','Bài học Máy thiết bị – hao mòn');

/* ===== Máy thiết bị: thị trường & thu nhập (mở rộng) ===== */
q(3,'may_tn','Dự án đầu tư có NPV dương ở tỷ suất chiết khấu r. Kết luận nào đúng?',['IRR lớn hơn r','IRR nhỏ hơn r','IRR bằng 0','Không thể so sánh IRR với r'],0,'NPV > 0 đồng nghĩa IRR > r: dự án tạo ra tỷ suất sinh lời cao hơn chi phí vốn nên chấp nhận được. Hai dự án loại trừ nhau thì chọn NPV lớn hơn.','Bài học Máy thiết bị – thu nhập');
q(3,'may_tn','Cấu trúc vốn gồm vốn chủ 60% (re = 15%) và vốn vay 40% (rd = 10%), thuế TNDN 20%. WACC là:',['11,4%','12,2%','12,4%','13,0%'],1,'WACC = E% × re + D% × rd × (1 − t) = 0,6 × 15% + 0,4 × 10% × 0,8 = 9% + 3,2% = 12,2%. (13,0% là quên nhân (1 − t) cho chi phí vay.)','Bài học Máy thiết bị – thu nhập');
q(3,'may_tn','Giá trị thu hồi cuối kỳ của dây chuyền là 200 triệu đồng, thuế suất TNDN 20%. Khoản đưa vào dòng tiền (trước chiết khấu) là:',['200 triệu đồng','160 triệu đồng','40 triệu đồng','240 triệu đồng'],1,'Giá trị thu hồi cần tính sau thuế: 200 × (1 − 20%) = 160 triệu, rồi mới chiết khấu về hiện tại.','Bài học Máy thiết bị – thu nhập');

/* ===== Tài sản vô hình (mở rộng) ===== */
q(3,'tsvh','Đặc điểm nào sau đây KHÔNG phải của tài sản vô hình?',['Không có hình thái vật chất','Được pháp luật công nhận và bảo vệ','Có hình thái vật chất cụ thể','Có khả năng tạo thu nhập'],2,'Năm đặc điểm: không có hình thái vật chất; nhận biết được và có bằng chứng tồn tại; được pháp luật công nhận, bảo vệ, có thể sở hữu và chuyển giao; có khả năng tạo thu nhập; giá trị có thể định lượng.','Bài học Tài sản vô hình');
q(3,'tsvh','Theo phương pháp tiền sử dụng tài sản vô hình, giá trị tài sản vô hình là:',['Tổng chi phí nghiên cứu đã chi','Hiện giá của khoản tiền sử dụng tiết kiệm được sau thuế nhờ sở hữu tài sản','Giá bán của tài sản vật chất đi kèm','Vốn điều lệ của doanh nghiệp'],1,'Giả định doanh nghiệp phải thuê tài sản vô hình; khoản tiền sử dụng tiết kiệm được nhờ sở hữu, sau thuế, được chiết khấu về hiện tại. Dòng tiền, thuế và chi phí duy trì phải nhất quán.','Bài học Tài sản vô hình – thu nhập');
q(3,'tsvh','Trong phương pháp thu nhập tăng thêm đối với tài sản vô hình, bước thứ ba là:',['Chiết khấu về hiện tại','Xác định khoản đóng góp của các tài sản đóng góp (giá trị thị trường × tỷ suất sinh lời hợp lý)','Dự báo doanh thu','Tính tuổi đời kinh tế'],1,'Năm bước: doanh thu kỳ vọng; thu nhập ròng sau chi phí, khấu hao, thuế; đóng góp của các tài sản khác; thu nhập riêng của tài sản vô hình = thu nhập ròng − đóng góp các tài sản khác; chiết khấu về hiện tại.','Bài học Tài sản vô hình – thu nhập tăng thêm');

/* ===== Vận dụng (mở rộng) ===== */
q(2,'vandung','Tài sản sinh lời R0 = 12%, vay D/V = 40% với lãi vay i = 9%. Tỷ suất sinh lợi trên vốn chủ ROE là:',['8,4%','12%','13,5%','14%'],3,'ROE = [R0 − i × (D/V)] / (E/V) = (12% − 9% × 0,4) / 0,6 = (12% − 3,6%) / 0,6 = 14%. Vay có lợi vì lãi vay (9%) thấp hơn tỷ suất sinh lợi tài sản (12%).','Bài học Vận dụng – đòn bẩy tài chính');
q(2,'vandung','Lãi suất danh nghĩa 8%/năm ghép lãi nửa năm một lần. Lãi suất thực hằng năm là:',['8,00%','8,16%','8,24%','4,00%'],1,'Lãi thực = (1 + 8%/2)^2 − 1 = 1,04^2 − 1 = 8,16%. Dùng lãi suất thực để so sánh các nguồn vốn có kỳ ghép lãi khác nhau.','Bài học Vận dụng – lãi suất thực');

export { Q };
